window.VIVEK_GROUPS=[{"key": "pub", "zh": "出版說明", "hi": "प्रकाशकीय", "pages": "PDF 7–8", "note": "1963 年 8 月，出版者署名", "count": 24, "headings": ["प्रकाशकीय", "अगस्त, १९६३", "प्रकाशक"], "footnotes": [], "rom": "Prakāśakīya", "headingsRom": ["Prakāśakīya", "Agasta, 1963", "Prakāśaka"], "footnotesRom": []}, {"key": "preface", "zh": "序言", "hi": "भूमिका〈我們的上師與祂的訊息〉", "pages": "PDF 13–20", "note": "書頁 क–छ，文末署名：尼維迪塔，1907 年 7 月 4 日", "count": 112, "headings": ["भूमिका", "हमारे गुरु और उनका सन्देश", "४ जुलाई, १९०७", "—भगिनी निवेदिता"], "footnotes": ["१. अब हिन्दी में दस खण्डों में प्रकाशित। सं०", "१. गीता ॥७॥७॥", "२. यद्यद्विभूतिमत्सत्त्वं श्रीमदूर्जितमेव वा। तत्तदेवावगच्छ त्वं मम तेजोंऽशसंभवम् ॥गीता ॥१०॥४१॥", "१. शृण्वन्तु विश्वे अमृतस्य पुत्रा आ ये धामानि दिव्यानि तस्थुः। वेदाहमेतं पुरुषं महान्तं आदित्यवर्णं तमसः परस्तात्। तमेव विदित्वाति मृत्युमेति नान्यः पन्था विद्यतेऽयनाय॥ —श्वेताश्वतरोपनिषद् ॥२।५; ३।८॥", "२. द्र० विवेकानन्द साहित्य, पंचम खण्ड, पृ० १६३।"], "rom": "Bhūmikā〈我們的上師與祂的訊息〉", "headingsRom": ["Bhūmikā", "Hamāre guru aura unakā sandesha", "4 Julāī, 1907", "—Bhaginī Niveditā"], "footnotesRom": ["1. Aba hindī meṁ dasa khaṇḍoṁ meṁ prakāśita। Saṁ.", "1. Gītā ॥7॥7॥", "2. Yad yad vibhūtimat sattvaṁ śrīmad ūrjitam eva vā। Tat tad evāvagaccha tvaṁ mama tejo'ṁśasaṁbhavam ॥Gītā ॥10॥41॥", "1. Śṛṇvantu viśve amṛtasya putrā ā ye dhāmāni divyāni tasthuḥ। Vedāham etaṁ puruṣaṁ mahāntaṁ ādityavarṇaṁ tamasaḥ parastāt। Tam eva viditvāti mṛtyumeti nānyaḥ panthā vidyate'yanāya॥ —Śvetāśvataropaniṣad ॥2।5; 3।8॥", "2. Dra. Vivekānanda sāhitya, pañcama khaṇḍa, pṛ. 163।"]}, {"key": "nivedita", "zh": "尼維迪塔短文", "hi": "स्वामी विवेकानन्द", "pages": "PDF 21–22", "note": "書頁 ज–त，作者：尼維迪塔修女", "count": 24, "headings": ["स्वामी विवेकानन्द", "—भगिनी निवेदिता"], "footnotes": [], "rom": "Svāmī Vivekānanda", "headingsRom": ["Svāmī Vivekānanda", "—Bhaginī Niveditā"], "footnotesRom": []}, {"key": "welcome", "zh": "歡迎辭回覆", "hi": "धर्म-महासभा : स्वागत का उत्तर", "pages": "書頁 3–4", "note": "芝加哥世界宗教大會，1893 年 9 月 11 日", "count": 18, "headings": ["धर्म-महासभा : स्वागत का उत्तर\n(विश्व-धर्म-महासभा, शिकागो, ११ सितम्बर, १८९३ ई०)"], "footnotes": ["रुचीनां वैचित्र्यादृजुकुटिलनानापथजुषाम् ।\nनृणामेको गम्यस्त्वमसि पयसामर्णव इव ॥", "ये यथा मां प्रपद्यन्ते तांस्तथैव भजाम्यहम् ।\nमम वर्त्मानुवर्तन्ते मनुष्याः पार्थ सर्वशः ॥", "१. शिवमहिम्नस्तोत्रम् ॥१॥", "२. गीता ॥४।११॥"], "rom": "Dharma-mahāsabhā : svāgata kā uttara", "headingsRom": ["Dharma-mahāsabhā : svāgata kā uttara\n(Viśva-dharma-mahāsabhā, Śikāgo, 11 Sitambara, 1893 Ī.)"], "footnotesRom": ["Rucīnāṁ vaicitryād ṛjukuṭilanānāpathajuṣām ।\nNṛṇām eko gamyas tvam asi payasām arṇava iva ॥", "Ye yathā māṁ prapadyante tāṁs tathaiva bhajāmy aham ।\nMama vartmānuvartante manuṣyāḥ pārtha sarvaśaḥ ॥", "1. Śivamahimnastotram ॥1॥", "2. Gītā ॥4।11॥"]}, {"key": "frog", "zh": "我們的分歧原因", "hi": "हमारे मतभेद का कारण", "pages": "書頁 5–6", "note": "芝加哥世界宗教大會，1893 年 9 月 15 日，青蛙故事", "count": 29, "headings": ["हमारे मतभेद का कारण\n(१५ सितम्बर, १८९३ ई०)"], "footnotes": ["१. १५ सितम्बर, शुक्रवार के अपराह्न में धर्म-महासभा के पंचम दिवस के अधिवेशन के समय भिन्न भिन्न धर्मावलम्बी अपने अपने धर्म की प्रधानता का प्रतिपादन करने के लिए वितण्डावाद में जुट गये थे। अन्त में स्वामी विवेकानन्द ने यह कहानी सुनाकर सबको शान्त कर दिया। सं०", "२. सब बीमारियाँ कीड़ों से उत्पन्न होती हैं, अतएव कीड़ों को नष्ट करना चाहिए—यह इन लोगों का मत है। सं०"], "rom": "Hamāre matabheda kā kāraṇa", "headingsRom": ["Hamāre matabheda kā kāraṇa\n(15 Sitambara, 1893 Ī.)"], "footnotesRom": ["1. 15 Sitambara, śukravāra ke aparāhṇa meṁ dharma-mahāsabhā ke pañcama divasa ke adhiveśana ke samaya bhinna bhinna dharmāvalambī apane apane dharma kī pradhānatā kā pratipādana karane ke lie vitaṇḍāvāda meṁ juṭa gaye the। Anta meṁ svāmī Vivekānanda ne yaha kahānī sunākara sabako śānta kara diyā। Saṁ.", "2. Sab bīmāriyāṁ kīṛoṁ se utpanna hotī haiṁ, ataeva kīṛoṁ ko naṣṭa karanā cāhie—yaha ina logoṁ kā mata hai। Saṁ."]}, {"key": "hindu", "zh": "印度教論文（開頭）", "hi": "हिंदू धर्म पर निबन्ध", "pages": "書頁 7–8", "note": "芝加哥世界宗教大會，1893 年 9 月 19 日宣讀，本批在句中斷", "count": 31, "headings": ["हिंदू धर्म पर निबन्ध\n(धर्म-महासभा में, १९ सितम्बर, १८९३ ई० को पठित)"], "footnotes": [], "rom": "Hindū dharma para nibandha", "headingsRom": ["Hindū dharma para nibandha\n(Dharma-mahāsabhā meṁ, 19 Sitambara, 1893 Ī. ko paṭhita)"], "footnotesRom": []}];
window.VIVEK_CARDS=[{"id": "P07-02", "g": "pub", "pdf": 7, "book": null, "hi": "भारत एवं विदेशों में अपनी साधुता, स्वदेश-भक्ति, सम्पूर्ण मानव-जाति के आध्यात्मिक उत्थान एवं प्राच्य तथा पाश्चात्य के मध्य भ्रातृभाव के सार्वभौमिक संदेश के लिए सुपरिचित स्वामी विवेकानन्द को किसी भूमिका की आवश्यकता नहीं है।", "rom": "Bhārata evaṃ videśoṃ meṃ apanī sādhutā, svadeśa-bhakti, sampūrṇa mānava-jāti ke ādhyātmika utthāna evaṃ prācya tathā pāścātya ke madhya bhrātṛbhāva ke sārvabhaumika saṃdeśa ke liye suparicita Svāmī Vivekānanda ko kisī bhūmikā kī āvaśyakatā nahīṃ hai.", "zh": "在印度與國外，以其聖者風範、愛國之心、為全人類的精神提升以及東西方之間兄弟情誼的普世訊息而廣為人知的維韋卡南達，不需要任何序言。", "st": "complete", "doubt": false}, {"id": "P07-03", "g": "pub", "pdf": 7, "book": null, "hi": "फिर भी भारत के हिन्दी भाषा-भाषियों को अब तक यह अवसर न मिल पाया था कि वे उनकी सम्पूर्ण कृतियों को हिन्दी भाषा में उपलब्ध कर अध्ययन कर सकें, जो स्वच्छ एवं आकर्षक ग्रंथों में सुपाठ्य एवं विश्वसनीय अनुवाद के माध्यम से प्रस्तुत की गयी हो।", "rom": "Phira bhī Bhārata ke Hindī bhāṣā-bhāṣiyoṃ ko aba taka yaha avasara na mila pāyā thā ki ve unakī sampūrṇa kṛtiyoṃ ko Hindī bhāṣā meṃ upalabdha kara adhyayana kara sakeṃ, jo svaccha evaṃ ākarṣaka graṃthoṃ meṃ supāṭhya evaṃ viśvasanīya anuvāda ke mādhyama se prastuta kī gayī ho.", "zh": "然而，印度的印地語讀者至今還沒有這樣的機會：能以印地語取得他的全部著作來研讀，這些著作是以清晰、美觀的書冊中易讀且可信的翻譯來呈現的。", "st": "complete", "doubt": false}, {"id": "P07-04", "g": "pub", "pdf": 7, "book": null, "hi": "अद्वैत आश्रम, मायावती, अल्मोड़ा बहुत दिनों से इन बहुमूल्य कृतियों को हिन्दी में प्रकाशित करने का विचार कर रहा था।", "rom": "Advaita Āśrama, Māyāvatī, Almoṛā bahuta dinoṃ se ina bahumūlya kṛtiyoṃ ko Hindī meṃ prakāśita karane kā vicāra kara rahā thā.", "zh": "位於阿爾莫拉馬雅瓦蒂的阿德維塔修道院（Advaita Ashrama）很久以來就在考慮以印地語出版這些珍貴的著作。", "st": "complete", "doubt": false}, {"id": "P07-05", "g": "pub", "pdf": 7, "book": null, "hi": "इसी उद्देश्य से इस आश्रम ने स्वामी जी की कुछ महत्त्वपूर्ण पुस्तकों का अनुवाद अपनी हिन्दी पत्रिका 'समन्वय' में प्रकाशित करना शुरू किया था।", "rom": "Isī uddeśya se isa Āśrama ne Svāmī jī kī kucha mahattvapūrṇa pustakoṃ kā anuvāda apanī Hindī patrikā 'Samanvaya' meṃ prakāśita karanā śurū kiyā thā.", "zh": "為此，該修道院開始在其印地語刊物《協調》（Samanvaya）上翻譯出版維韋卡南達大師的幾部重要著作。", "st": "complete", "doubt": false}, {"id": "P07-06", "g": "pub", "pdf": 7, "book": null, "hi": "यह पत्रिका अब बंद हो गयी है।", "rom": "Yaha patrikā aba baṃda ho gayī hai.", "zh": "這份刊物現在已經停刊了。", "st": "complete", "doubt": false}, {"id": "P07-07", "g": "pub", "pdf": 7, "book": null, "hi": "आश्रम को इस कार्य में सुप्रसिद्ध हिन्दी कवि श्री सूर्यकान्त त्रिपाठी 'निराला' से काफी सहायता मिली थी।", "rom": "Āśrama ko isa kārya meṃ suprasiddha Hindī kavi Śrī Sūryakānta Tripāṭhī 'Nirālā' se kāfī sahāyatā milī thī.", "zh": "修道院在這項工作中得到了著名印地語詩人蘇利耶康德·特里帕蒂「尼拉拉」的大力幫助。", "st": "complete", "doubt": false}, {"id": "P07-08", "g": "pub", "pdf": 7, "book": null, "hi": "चूँकि समुचित आर्थिक सहायता नहीं मिल सकी थी, इसलिए कुछ समय बाद इस प्रयास को त्याग देना पड़ा।", "rom": "Cūm̐ki samucita ārthika sahāyatā nahīṃ mila sakī thī, isaliye kucha samaya bāda isa prayāsa ko tyāga denā paṛā.", "zh": "由於得不到適當的經濟資助，過了一段時間之後，不得不放棄這一努力。", "st": "complete", "doubt": false}, {"id": "P07-09", "g": "pub", "pdf": 7, "book": null, "hi": "बाद में रामकृष्ण आश्रम, नागपुर ने इस कार्य को पुनः आरम्भ किया; लेकिन वह आश्रम भी इसे पूर्ण न कर सका।", "rom": "Bāda meṃ Rāmakṛṣṇa Āśrama, Nāgapura ne isa kārya ko punaḥ ārambha kiyā; lekina vaha Āśrama bhī ise pūrṇa na kara sakā.", "zh": "後來，那格浦爾的羅摩克里希納修道院重新開始了這項工作；但那個修道院也未能完成它。", "st": "complete", "doubt": false}, {"id": "P07-10", "g": "pub", "pdf": 7, "book": null, "hi": "साथ ही समयान्तर के साथ पुराने अनुवादों में सांगोपांग संशोधन-सम्पादन की आवश्यकता थी, जो प्रस्तुत ग्रंथों में उपलब्ध है।", "rom": "Sātha hī samayāntara ke sātha purāne anuvādoṃ meṃ sāṃgopāṃga saṃśodhana-sampādana kī āvaśyakatā thī, jo prastuta graṃthoṃ meṃ upalabdha hai.", "zh": "同時，隨著時間推移，舊譯本需要全面修訂編輯，這在目前的這幾冊書中已經有了。", "st": "complete", "doubt": false}, {"id": "P07-11", "g": "pub", "pdf": 7, "book": null, "hi": "यहीं तक नहीं, किसी किसी स्थल पर इन अनुवादों को योग्य विद्वानों द्वारा पर्याप्त नया रूप दिया गया है; अतः वर्तमान कृतियाँ केवल पुराने संस्करण की पुनरावृत्ति मात्र नहीं हैं, यद्यपि हमें इनसे काफी सहायता मिली है।", "rom": "Yahīṃ taka nahīṃ, kisī kisī sthala para ina anuvādoṃ ko yogya vidvānoṃ dvārā paryāpta nayā rūpa diyā gayā hai; ataḥ vartamāna kṛtiyāṃ kevala purāne saṃskaraṇa kī punarāvṛtti mātra nahīṃ haiṃ, yadyapi hameṃ inase kāfī sahāyatā milī hai.", "zh": "不僅如此，在某些地方，這些譯本經由有能力的學者做了相當程度的改寫；因此，現在的著作並不僅僅是舊版的重印，雖然我們從舊版得到了很大的幫助。", "st": "complete", "doubt": false}, {"id": "P07-12", "g": "pub", "pdf": 7, "book": null, "hi": "इसके अतिरिक्त अब तक हिन्दी में अप्रकाशित स्वामी जी के अनेक भाषण, लेख आदि का अनुवाद भी इसमें संयोजित किया गया है।", "rom": "Isake atirikta aba taka Hindī meṃ aprakāśita Svāmī jī ke aneka bhāṣaṇa, lekha ādi kā anuvāda bhī isameṃ saṃyojita kiyā gayā hai.", "zh": "此外，至今未以印地語出版的維韋卡南達大師的許多演講、文章等，其翻譯也收錄在其中。", "st": "complete", "doubt": false}, {"id": "P07-13", "g": "pub", "pdf": 7, "book": null, "hi": "स्वामी विवेकानन्द की जन्मशती (१९६३-६४), जो सम्पूर्ण भारत एवं विदेशों में मनायी जा रही है, के अवसर पर इन ग्रंथों को हम दस खण्डों में जनता के सम्मुख उपस्थित कर रहे हैं।", "rom": "Svāmī Vivekānanda kī janmaśatī (1963-64), jo sampūrṇa Bhārata evaṃ videśoṃ meṃ manāyī jā rahī hai, ke avasara para ina graṃthoṃ ko hama dasa khaṇḍoṃ meṃ janatā ke sammukha upasthita kara rahe haiṃ.", "zh": "適逢維韋卡南達誕辰百年（1963–64），這一紀念活動正在全印度和國外舉行，我們正把這些著作以十卷的形式呈獻給大眾。", "st": "complete", "doubt": false}, {"id": "P07-14", "g": "pub", "pdf": 7, "book": null, "hi": "आनन्द की बात है कि भारत के अन्य क्षेत्रों में भी, जैसे बंगाल, उड़ीसा, आन्ध्र, तमिलनाड, मैसूर, केरल, महाराष्ट्र एवं गुजरात में, इन ग्रंथों को प्रान्तीय भाषाओं में प्रकाशित किया जा रहा है।", "rom": "Ānanda kī bāta hai ki Bhārata ke anya kṣetroṃ meṃ bhī, jaise Baṃgāla, Uṛīsā, Āndhra, Tamilanāḍa, Maisūra, Kerala, Mahārāṣṭra evaṃ Gujarāta meṃ, ina graṃthoṃ ko prāntīya bhāṣāoṃ meṃ prakāśita kiyā jā rahā hai.", "zh": "令人欣慰的是，在印度的其他地區，例如孟加拉、奧里薩、安得拉、泰米爾納德、邁索爾、喀拉拉、馬哈拉施特拉和古吉拉特，這些著作也正在以當地語言出版。", "st": "complete", "doubt": false}, {"id": "P07-15", "g": "pub", "pdf": 8, "book": null, "hi": "केन्द्रीय सरकार तथा उत्तर प्रदेश, बिहार एवं मध्य प्रदेश सरकारों की उदारतापूर्ण सहायता से यह कष्टसाध्य एवं महँगा प्रयास सफल हो पाया; इन सरकारों ने इस लक्ष्य की पूर्ति के लिए विभिन्न परिमाणों में आर्थिक सहायता दी; पर व्यय का अधिकांश अंश आश्रम को ही वहन करना पड़ा है।", "rom": "Kendrīya sarakāra tathā Uttara Pradeśa, Bihāra evaṃ Madhya Pradeśa sarakāroṃ kī udāratāpūrṇa sahāyatā se yaha kaṣṭasādhya evaṃ mahaṃgā prayāsa saphala ho pāyā; ina sarakāroṃ ne isa lakṣya kī pūrti ke liye vibhinna parimāṇoṃ meṃ ārthika sahāyatā dī; para vyaya kā adhikāṃśa aṃśa Āśrama ko hī vahana karanā paṛā hai.", "zh": "在中央政府以及北方邦、比哈爾邦和中央邦政府的慷慨資助下，這項艱鉅而昂貴的努力得以成功；這些政府為實現這一目標提供了不同數額的經濟資助；但大部分費用仍須由修道院自己承擔。", "st": "complete", "doubt": false}, {"id": "P07-16", "g": "pub", "pdf": 8, "book": null, "hi": "सरकारी सहायता के कारण ही इन ग्रंथों का इतने सस्ते मूल्य पर वितरण सम्भव हो पाया।", "rom": "Sarakārī sahāyatā ke kāraṇa hī ina graṃthoṃ kā itane saste mūlya para vitaraṇa sambhava ho pāyā.", "zh": "正是因為政府的資助，這些著作才能以如此低廉的價格發行。", "st": "complete", "doubt": false}, {"id": "P07-17", "g": "pub", "pdf": 8, "book": null, "hi": "अतः इस आर्थिक सहायता के लिए हम सभी सरकारों के प्रति आभारी हैं।", "rom": "Ataḥ isa ārthika sahāyatā ke liye hama sabhī sarakāroṃ ke prati ābhārī haiṃ.", "zh": "因此，對於這項經濟資助，我們對所有政府表示感謝。", "st": "complete", "doubt": false}, {"id": "P07-18", "g": "pub", "pdf": 8, "book": null, "hi": "अनुवाद के लिए हमें निम्नांकित विद्वानों का सहयोग मिला है, जिनके प्रति हम हार्दिक धन्यवाद प्रकट करते हैं:", "rom": "Anuvāda ke liye hameṃ nimnāṃkita vidvānoṃ kā sahayoga milā hai, jinake prati hama hārdika dhanyavāda prakaṭa karate haiṃ:", "zh": "在翻譯方面，我們得到了以下學者的協助，對他們我們表示衷心的感謝：", "st": "complete", "doubt": false}, {"id": "P07-19", "g": "pub", "pdf": 8, "book": null, "hi": "पंडित सुमित्रानन्दन पन्त, डॉ० प्रभाकर माचवे, श्री फणीश्वरनाथ 'रेणु', श्री भगवान् जी ओझा, डॉ० नर्मदेश्वर प्रसाद, श्री आत्माराम शाह, डॉ० नित्यानन्द मिश्र, डॉ० मदनमोहन सहाय, श्री रामबद्र राव, श्री गंगारत्न पाण्डे, श्री रामचन्द्र तिवारी, श्री एम० एल० द्विवेदी, श्री दूधनाथ सिंह, श्री ब्रजमोहन अवस्थी, श्री ब्रजनन्दन सिंह इत्यादि।", "rom": "Paṇḍita Sumitrānandana Panta, Ḍā. Prabhākara Mācave, Śrī Phaṇīśvaranātha 'Reṇu', Śrī Bhagavān jī Ojhā, Ḍā. Narmadeśvara Prasāda, Śrī Ātmārāma Śāha, Ḍā. Nityānanda Miśra, Ḍā. Madanamohana Sahāya, Śrī Rāmabadra Rāva, Śrī Gaṃgāratna Pāṇḍe, Śrī Rāmacandra Tivārī, Śrī Ema. Ela. Dvivedī, Śrī Dūdhanātha Siṃha, Śrī Brajamohana Avasthī, Śrī Brajanandana Siṃha ityādi.", "zh": "潘迪特·蘇米特拉南丹·潘特、普拉巴卡爾·馬奇韋博士、帕尼什瓦爾納特「雷努」先生、巴格萬·吉·奧賈先生、納爾馬代什瓦爾·普拉薩德博士、阿特馬拉姆·沙阿先生、尼提亞南德·米什拉博士、馬丹莫漢·薩哈伊博士、拉姆巴德拉·拉奧先生、甘加拉特納·潘德先生、拉姆錢德拉·蒂瓦里先生、M. L. 德維維迪先生、杜德納特·辛格先生、布拉傑莫漢·阿瓦斯蒂先生、布拉傑南丹·辛格先生，等等。", "st": "complete", "doubt": false}, {"id": "P07-20", "g": "pub", "pdf": 8, "book": null, "hi": "डॉ० रघुवंश, श्री आत्माराम शाह तथा अन्य विद्वानों के प्रति हम कृतज्ञ हैं, जिन्होंने सम्पादनादि कार्य में हमें सहायता दी है।", "rom": "Ḍā. Raghuvaṃśa, Śrī Ātmārāma Śāha tathā anya vidvānoṃ ke prati hama kṛtajña haiṃ, jinhone sampādanādi kārya meṃ hameṃ sahāyatā dī hai.", "zh": "對於拉古萬什博士、阿特馬拉姆·沙阿先生以及其他學者，我們表示感激，他們在編輯等工作中給予了我們幫助。", "st": "complete", "doubt": false}, {"id": "P07-21", "g": "pub", "pdf": 8, "book": null, "hi": "हम पंडित सुमित्रानन्दन पन्त के प्रति विशेष रूप से आभारी हैं, जिन्होंने इस कार्य में गहरी दिलचस्पी ली एवं स्वामी जी के कई पद्यों का अनुवाद किया, जो दशम खण्ड में प्रकाशित हैं।", "rom": "Hama Paṇḍita Sumitrānandana Panta ke prati viśeṣa rūpa se ābhārī haiṃ, jinhone isa kārya meṃ gaharī dilacaspī lī evaṃ Svāmī jī ke kaī padyoṃ kā anuvāda kiyā, jo daśama khaṇḍa meṃ prakāśita haiṃ.", "zh": "我們特別感謝潘迪特·蘇米特拉南丹·潘特，他對這項工作表現出深厚的興趣，並翻譯了維韋卡南達大師的許多詩篇，這些詩篇刊載於第十卷。", "st": "complete", "doubt": false}, {"id": "P07-22", "g": "pub", "pdf": 8, "book": null, "hi": "'निराला' जी द्वारा अनूदित पद्य नवम खण्ड में प्रकाशित हैं।", "rom": "'Nirālā' jī dvārā anūdita padya navama khaṇḍa meṃ prakāśita haiṃ.", "zh": "「尼拉拉」翻譯的詩篇刊載於第九卷。", "st": "complete", "doubt": false}, {"id": "P07-23", "g": "pub", "pdf": 8, "book": null, "hi": "कुमारी निर्मला वर्मा ने अनुक्रमणिका तैयार करने एवं श्री श्रीराम वर्मा तथा श्री लल्लन सिंह ने प्रूफ-संशोधन तथा अन्य प्रकार से सहयोग दिये हैं।", "rom": "Kumārī Nirmalā Varmā ne anukramaṇikā taiyāra karane evaṃ Śrī Śrīrāma Varmā tathā Śrī Lallana Siṃha ne prūpha-saṃśodhana tathā anya prakāra se sahayoga diye haiṃ.", "zh": "庫瑪麗·尼爾瑪拉·瓦爾瑪編製了索引，施里拉姆·瓦爾瑪先生和拉蘭·辛格先生在校對和其他方面給予了協助。", "st": "complete", "doubt": false}, {"id": "P07-24", "g": "pub", "pdf": 8, "book": null, "hi": "इसके अतिरिक्त हम अनेक मित्रों के भी कृतज्ञ हैं, जिन्होंने इस कार्य में हमें विभिन्न रूपों से सहायता दी है।", "rom": "Isake atirikta hama aneka mitroṃ ke bhī kṛtajña haiṃ, jinhone isa kārya meṃ hameṃ vibhinna rūpoṃ se sahāyatā dī hai.", "zh": "此外，我們也感謝許多朋友，他們以各種方式在這項工作中幫助了我們。", "st": "complete", "doubt": false}, {"id": "P07-25", "g": "pub", "pdf": 8, "book": null, "hi": "सम्मेलन मुद्रणालय के प्रति हम उसके निपुण कार्य एवं पूर्ण सहयोग के लिए आभारी हैं।", "rom": "Sammelana Mudraṇālaya ke prati hama usake nipuṇa kārya evaṃ pūrṇa sahayoga ke liye ābhārī haiṃ.", "zh": "對於會議印刷所（Sammelan Mudranalaya），我們感謝它精湛的工作和充分的合作。", "st": "complete", "doubt": false}, {"id": "P13-03", "g": "preface", "pdf": 13, "book": null, "hi": "प्रस्तुत संस्करण में संकलित स्वामी विवेकानन्द की कृतियों के चार खंडों में हमें समग्र संसार के प्रति केवल धर्म का शुभ सन्देश ही नहीं, बल्कि इस देश की संतति के लिए भी हिन्दू धर्म की सनद मिलती है।", "rom": "Prastuta saṃskaraṇa mēṃ saṅkalita svāmī vivēkānanda kī kṛtiyōṃ kē cāra khaṇḍōṃ mēṃ hamēṃ samagra saṃsāra kē prati kēvala dharma kā śubha sandēśa hī nahīṃ, balki isa dēśa kī saṃtati kē liē bhī hindū dharma kī sanada milatī hai.", "zh": "在本版所收錄的維韋卡南達著作四卷中，我們得到的，不僅是對整個世界的一份宗教善訊，而且也是為這個國家的後代而立的印度教的憑證。", "st": "complete", "doubt": false}, {"id": "P13-04", "g": "preface", "pdf": 13, "book": null, "hi": "आधुनिक युग के विश्वव्यापी विघटनशील वातावरण में हिन्दू धर्म को आवश्यकता थी एक ऐसी चट्टान की, जहाँ वह लंगर डाल सके, एक ऐसी प्रामाणिक वाणी की, जिसमें वह स्वयं को पहचान सके।", "rom": "Ādhunika yuga kē viśvavyāpī vighaṭanaśīla vātāvaraṇa mēṃ hindū dharma kō āvaśyakatā thī ēka aisī caṭṭāna kī, jahāṃ vaha laṅgara ḍāla sakē, ēka aisī prāmāṇika vāṇī kī, jisamēṃ vaha svayaṃ kō pahacāna sakē.", "zh": "在現代這個世界性分裂氛圍的時代，印度教需要一塊磐石，可以在那裡下錨；需要一種真實可信的聲音，可以在其中認出自己。", "st": "complete", "doubt": false}, {"id": "P13-05", "g": "preface", "pdf": 13, "book": null, "hi": "स्वामी विवेकानन्द के इन शब्दों और कृतियों में हिन्दू धर्म को यह वरदान उपलब्ध हो गया।", "rom": "Svāmī vivēkānanda kē ina śabdōṃ aura kṛtiyōṃ mēṃ hindū dharma kō yaha varadāna upalabdha hō gayā.", "zh": "在維韋卡南達的這些話語與著作中，印度教得到了這份恩賜。", "st": "complete", "doubt": false}, {"id": "P13-06", "g": "preface", "pdf": 13, "book": null, "hi": "जैसा अन्यत्र कहा गया है, यहाँ इतिहास में पहली बार स्वयं हिन्दू धर्म ही एक उच्चतम कोटि की हिन्दू प्रतिभा के सामान्यीकरण का विषय बना है।", "rom": "Jaisā anyatra kahā gayā hai, yahāṃ itihāsa mēṃ pahalī bāra svayaṃ hindū dharma hī ēka uccatama kōṭi kī hindū pratibhā kē sāmānyīkaraṇa kā viṣaya banā hai.", "zh": "如別處所說，在這裡，歷史上第一次，印度教本身成為一位最高等級的印度教天才所普遍化闡述的對象。", "st": "complete", "doubt": false}, {"id": "P13-07", "g": "preface", "pdf": 13, "book": null, "hi": "युग युग तक अपने पूर्वजों के धार्मिक आदर्शों-विश्वासों को परखनेवाला हिन्दू भाई तथा बाल-बच्चों को उनकी शिक्षा देनेवाली हिन्दू माता आश्वासन और प्रकाश के लिए इन पुस्तकों के पृष्ठ पलटेगी।", "rom": "Yuga yuga taka apanē pūrvajōṃ kē dhārmika ādarśōṃ-viśvāsōṃ kō parakhanēvālā hindū bhāī tathā bāla-baccōṃ kō unakī śikṣā dēnēvālī hindū mātā āśvāsana aura prakāśa kē liē ina pustakōṃ kē pṛṣṭha palaṭēgī.", "zh": "世世代代以來檢驗祖先宗教理想與信仰的印度教兄弟，以及教導孩子們這些教導的印度教母親，將為了安慰與光明而翻閱這些書的書頁。", "st": "complete", "doubt": false}, {"id": "P13-08", "g": "preface", "pdf": 13, "book": null, "hi": "भारत में अंग्रेजी के लुप्त हो जाने के बाद भी बहुत दिन तक, उस भाषा के माध्यम से विश्व को प्राप्त हुई यह देन अक्षुण्ण रहेगी और पूर्व तथा पश्चिम को समान रूप से सुफल प्रदान करती रहेगी।", "rom": "Bhārata mēṃ aṅgrēzī kē lupta hō jānē kē bāda bhī bahuta dina taka, usa bhāṣā kē mādhyama sē viśva kō prāpta huī yaha dēna akṣuṇṇa rahēgī aura pūrva tathā paścima kō samāna rūpa sē suphala pradāna karatī rahēgī.", "zh": "即使在英國統治從印度消失之後很久，世界透過那種語言所獲得的這份贈禮仍將完好無損，並將同等地為東方與西方帶來美好的果實。", "st": "complete", "doubt": false}, {"id": "P13-09", "g": "preface", "pdf": 13, "book": null, "hi": "हिन्दू धर्म को आवश्यकता थी अपने ही भावादर्शों को सुव्यवस्थित और सुगठित करने की और संसार को ज़रूरत थी सत्य से भयभीत न होनेवाले एक धर्म की।", "rom": "Hindū dharma kō āvaśyakatā thī apanē hī bhāvādarśōṃ kō suvyavasthita aura sugaṭhita karanē kī aura saṃsāra kō zarūrata thī satya sē bhayabhīta na hōnēvālē ēka dharma kī.", "zh": "印度教需要把自己的理想有條理地、緊密地組織起來，而世界需要一種不畏懼真理的宗教。", "st": "complete", "doubt": false}, {"id": "P13-10", "g": "preface", "pdf": 13, "book": null, "hi": "ये दोनों ही यहाँ उपलब्ध हैं।", "rom": "Yē dōnōṃ hī yahāṃ upalabdha haiṃ.", "zh": "這兩者在此都已具備。", "st": "complete", "doubt": false}, {"id": "P13-11", "g": "preface", "pdf": 13, "book": null, "hi": "संकट के क्षणों में जातीय चेतना को एकत्र करने और वाणी प्रदान करनेवाले व्यक्ति के इस आविर्भाव से बढ़कर सनातन धर्म की अनन्त प्राणशक्ति का, और इस सत्य का कोई दूसरा महत्तर प्रमाण नहीं दिया जा सकता था कि भारत आज भी उतना ही महान् है, जितना कि वह अतीत में सदा रहा है।", "rom": "Saṅkaṭa kē kṣaṇōṃ mēṃ jātīya cētanā kō ēkatra karanē aura vāṇī pradāna karanēvālē vyakti kē isa āvirbhāva sē baṛhakara sanātana dharma kī ananta prāṇaśakti kā, aura isa satya kā kōī dūsarā mahattara pramāṇa nahīṃ diyā jā sakatā thā ki bhārata āja bhī utanā hī mahān hai, jitanā ki vaha atīta mēṃ sadā rahā hai.", "zh": "在危難時刻凝聚民族意識並賦予其聲音的這位人物的出現，本身就是對永恆宗教無限生命力的、以及對「印度今天依然和過去一向同樣偉大」這一真理的、再也沒有比這更偉大的證明。", "st": "complete", "doubt": false}, {"id": "P13-12", "g": "preface", "pdf": 13, "book": null, "hi": "सम्भवतः इस बात का पूर्व-ज्ञान रहा हो कि भारत अपनी आवश्यकता के प्रति संतुष्ट केवल तभी होगा, जब वह इस जीवनदायी सन्देश को अपनी सीमाओं के बाहर की मानव-जाति तक पहुँचाये।", "rom": "Sambhavataḥ isa bāta kā pūrva-jñāna rahā hō ki bhārata apanī āvaśyakatā kē prati saṃtuṣṭa kēvala tabhī hōgā, jaba vaha isa jīvanadāyī sandēśa kō apanī sīmāōṃ kē bāhara kī mānava-jāti taka pahum̐cāyē.", "zh": "或許早已預知，印度只有在把這賦予生命的訊息傳到自己疆界之外的人類那裡時，才會對自己的需要感到滿足。", "st": "complete", "doubt": false}, {"id": "P13-13", "g": "preface", "pdf": "13-14", "book": null, "hi": "ऐसा प्रथम बार केवल इसी अवसर पर घटित नहीं हुआ।", "rom": "Aisā prathama bāra kēvala isī avasara para ghaṭita nahīṃ huā.", "zh": "這樣的事並不是僅僅在這一次機會中才第一次發生。", "st": "complete", "doubt": false}, {"id": "P14-01", "g": "preface", "pdf": 14, "book": null, "hi": "एक बार पहले भी, एक राष्ट्र-निर्मायक धर्म का सन्देश बन्धु देशों को भेजकर समूचे भारत ने अपने चिन्तन की गरिमा समझी थी—एक ऐसा एकात्मीकरण, जिससे स्वयं आधुनिक हिन्दू धर्म का जन्म हुआ है।", "rom": "Ēka bāra pahalē bhī, ēka rāṣṭra-nirmāyaka dharma kā sandēśa bandhu dēśōṃ kō bhējakara samūcē bhārata nē apanē cintana kī garimā samajhī thī—ēka aisā ēkātamīkaraṇa, jisase svayaṃ ādhunika hindū dharma kā janma huā hai.", "zh": "在更早的一次，印度整體也曾把一種締造國家的宗教訊息送給兄弟國家，從而領會了自己思想的尊嚴——那是一種合一，由此，現代印度教本身誕生了。", "st": "complete", "doubt": false}, {"id": "P14-02", "g": "preface", "pdf": 14, "book": null, "hi": "हमें यह कभी न भुला देना चाहिए कि इसी भारत की भूमि पर सर्वप्रथम शिष्यों को अपने गुरु का यह आदेश श्रुतिगोचर हुआ था, “तुम सारे संसार में जाओ और जगत् के कोने कोने में प्राणिमात्र को धर्म का उपदेश करो।”", "rom": "Hamēṃ yaha kabhī na bhulā dēnā cāhiē ki isī bhārata kī bhūmi para sarvaprathama śiṣyōṃ kō apanē guru kā yaha ādēśa śrutigōcara huā thā, “Tuma sārē saṃsāra mēṃ jāō aura jagat kē kōnē kōnē mēṃ prāṇimātra kō dharma kā upadēśa karō.”", "zh": "我們絕不應忘記，在這片印度的土地上，弟子們最先親耳聽到自己上師的這道訓令：「你們要到整個世界去，向世間每個角落的一切生靈傳授宗教。」", "st": "complete", "doubt": false}, {"id": "P14-03", "g": "preface", "pdf": 14, "book": null, "hi": "यह वही विचार और प्रेम का वही आवेग है, जो एक नया रूप धारण करके, स्वामी विवेकानन्द के श्रीमुख से उस समय निःसृत हुआ, जब पश्चिम में एक महती सभा में उन्होंने कहा, “यदि एक धर्म सच्चा है, तब निश्चय ही अन्य सभी धर्म सच्चे हैं।", "rom": "Yaha vahī vicāra aura prēma kā vahī āvēga hai, jō ēka nayā rūpa dhāraṇa karakē, svāmī vivēkānanda kē śrīmukha sē usa samaya niḥsṛta huā, jaba paścima mēṃ ēka mahatī sabhā mēṃ unhōṃnē kahā, “Yadi ēka dharma saccā hai, taba niścaya hī anya sabhī dharma saccē haiṃ.", "zh": "這正是同樣的思想、同樣的愛的激情，它換了一個新的形式，從維韋卡南達的口中在那時流出，當時他在西方的一次盛大集會上說：「如果一種宗教是真的，那麼毫無疑問，所有其他宗教也都是真的。", "st": "complete", "doubt": false}, {"id": "P14-04", "g": "preface", "pdf": 14, "book": null, "hi": "अतएव हिन्दू धर्म उतना ही आपका है, जितना मेरा।”", "rom": "Ataēva hindū dharma utanā hī āpakā hai, jitanā mērā.”", "zh": "因此，印度教和屬於我一樣，也屬於你們。」", "st": "complete", "doubt": false}, {"id": "P14-05", "g": "preface", "pdf": 14, "book": null, "hi": "और इसी भाव को विशद करते हुए वे फिर कहते हैं, “हम हिन्दू केवल सहिष्णु ही नहीं हैं, हम अन्य धर्मों के साथ—मुसलमानों की मस्जिद में नमाज़ पढ़कर, पारसियों की अग्नि की उपासना करके तथा ईसाइयों के क्रूस के सम्मुख नतमस्तक होकर उनसे एकात्म हो जाते हैं।", "rom": "Aura isī bhāva kō viśada karatē huē vē phira kahatē haiṃ, “Hama hindū kēvala sahiṣṇu hī nahīṃ haiṃ, hama anya dharmōṃ kē sātha—musalamānōṃ kī masjida mēṃ namāza paṛhakara, pārasīyōṃ kī agni kī upāsanā karakē tathā īsāiyōṃ kē krūsa kē sammukha natamastaka hōkara unasē ēkātma hō jātē haiṃ.", "zh": "而在闡明同樣的心意時，他又說：「我們印度教徒不僅僅是寬容，我們還與其他宗教合而為一——在穆斯林的清真寺裡禮拜，在祆教徒的聖火前敬拜，在基督徒的十字架前低頭。", "st": "complete", "doubt": false}, {"id": "P14-06", "g": "preface", "pdf": 14, "book": null, "hi": "हम जानते हैं कि निम्नतम जड़-पूजावाद से लेकर उच्चतम निर्गुण ब्रह्मवाद तक सारे धर्म समान रूप से असीम को समझने और उसका साक्षात्कार करने के निमित्त मानवीय आत्मा के विविध प्रयास हैं।", "rom": "Hama jānatē haiṃ ki nimnatama jaṛa-pūjāvāda sē lēkara uccatama nirguṇa brahmavāda taka sārē dharma samāna rūpa sē asīma kō samajhanē aura usakā sākṣātkāra karanē kē nimitta mānavīya ātmā kē vividha prayāsa haiṃ.", "zh": "我們知道，從最低級的偶像崇拜到最高級的無屬性梵論，所有宗教同樣都是人類靈魂為了理解無限並親證無限而作的種種努力。", "st": "complete", "doubt": false}, {"id": "P14-07", "g": "preface", "pdf": 14, "book": null, "hi": "अतः हम इन सभी सुमनों को संचित करते हैं, और उन सबको प्रेमसूत्र में बाँधकर आराधना के निमित्त एक अद्भुत स्तवक निर्माण करते हैं।”", "rom": "Ataḥ hama ina sabhī sumanōṃ kō sañcita karatē haiṃ, aura una sabakō prēmasūtra mēṃ bāṃdhakara ārādhanā kē nimitta ēka adbhuta stavaka nirmāṇa karatē haiṃ.”", "zh": "因此，我們採集所有這些花朵，並用愛的絲線把它們繫在一起，為敬拜而編成一束奇妙的花束。」", "st": "complete", "doubt": false}, {"id": "P14-08", "g": "preface", "pdf": 14, "book": null, "hi": "इन वक्ता के हृदय के लिए कोई भी विदेशी या विजातीय नहीं था।", "rom": "Ina vaktā kē hṛdaya kē liē kōī bhī vidēśī yā vijātīya nahīṃ thā.", "zh": "對這位演說者的心而言，沒有任何人是外國人或異族。", "st": "complete", "doubt": false}, {"id": "P14-09", "g": "preface", "pdf": 14, "book": null, "hi": "इनके लिए केवल मानव-जाति और सत्य का ही अस्तित्व था।", "rom": "Inakē liē kēvala mānava-jāti aura satya kā hī astitva thā.", "zh": "對他而言，存在的只有人類與真理。", "st": "complete", "doubt": false}, {"id": "P14-10", "g": "preface", "pdf": 14, "book": null, "hi": "विश्व-धर्म-महासभा के सम्मुख स्वामी जी के अभिभाषण के सम्बन्ध में यह कहा जा सकता है कि जब उन्होंने अपना भाषण आरम्भ किया, तो विषय था, ‘हिन्दुओं के धार्मिक विचार’, किन्तु जब उन्होंने अंत किया, तब तक हिन्दू धर्म की सृष्टि हो चुकी थी।", "rom": "Viśva-dharma-mahāsabhā kē sammukha svāmī jī kē abhibhāṣaṇa kē sambandha mēṃ yaha kahā jā sakatā hai ki jaba unhōṃnē apanā bhāṣaṇa ārambha kiyā, tō viṣaya thā, ‘Hinduōṃ kē dhārmika vicāra’, kintu jaba unhōṃnē aṃta kiyā, taba taka hindū dharma kī sṛṣṭi hō cukī thī.", "zh": "關於維韋卡南達在世界宗教大會面前的演說，可以這樣說：當他開始演說時，主題是「印度教徒的宗教思想」，但當他結束時，印度教已經被創造出來了。", "st": "complete", "doubt": false}, {"id": "P14-11", "g": "preface", "pdf": 14, "book": null, "hi": "इस सम्भावना के लिए समय भी परिपक्व हो चुका था।", "rom": "Isa sambhāvanā kē liē samaya bhī paripakva hō cukā thā.", "zh": "為了這種可能性，時機也已經成熟。", "st": "complete", "doubt": false}, {"id": "P14-12", "g": "preface", "pdf": 14, "book": null, "hi": "उनके सम्मुख उपस्थित विशाल श्रोता-समूह पाश्चात्य विचारधारा का ही प्रतिनिधि था, लेकिन इसमें जो परमोत्कृष्ट विशिष्टता है, उस सबका कुछ विकास भी श्रोताओं में विद्यमान था।", "rom": "Unakē sammukha upasthita viśāla śrōtā-samūha pāścātya vicāradhārā kā hī pratinidhi thā, lēkina isamēṃ jō paramōtkṛṣṭa viśiṣṭatā hai, usa sabakā kucha vikāsa bhī śrōtāōṃ mēṃ vidyamāna thā.", "zh": "出現在他面前的廣大聽眾雖然是西方思想的代表，但其中最卓越的特質，也多少在聽眾身上有所發展。", "st": "complete", "doubt": false}, {"id": "P14-13", "g": "preface", "pdf": 14, "book": null, "hi": "अमेरिका को और विशेष रूप से शिकागो को, जहाँ यह सम्मेलन हुआ, यूरोप के प्रत्येक राष्ट्र ने अपने मानवीय योगदान से आप्लावित किया है।", "rom": "Amērikā kō aura viśēṣa rūpa sē śikāgō kō, jahāṃ yaha sammēlan huā, yūrōpa kē pratyēka rāṣṭra nē apanē mānavīya yōgadāna sē āplāvita kiyā hai.", "zh": "歐洲每一個國家都以自己的人文貢獻浸潤了美國，特別是這次大會舉行的芝加哥。", "st": "complete", "doubt": false}, {"id": "P14-14", "g": "preface", "pdf": 14, "book": null, "hi": "आधुनिक उद्योग और संघर्ष के बहुत कुछ उत्कृष्ट और उनमें से कुछ निकृष्ट भाव पश्चिम की इस नगरों की रानी की सीमाओं के भीतर मिलते हैं, जिसके पदतल—जब वह अपनी आँखों में उत्तर का प्रकाश भरकर बैठती और चिन्तामग्न होती है—मिशिगन झील के तट पर है।", "rom": "Ādhunika udyōga aura saṅgharṣa kē bahuta kucha utkṛṣṭa aura unamēṃ sē kucha nikṛṣṭa bhāva paścima kī isa nagarōṃ kī rānī kī sīmāōṃ kē bhītara milatē haiṃ, jisakē padatala—jaba vaha apanī āṃkhōṃ mēṃ uttara kā prakāśa bharakara baiṭhatī aura cintāmagna hōtī hai—miśigana jhīla kē taṭa para hai.", "zh": "現代工業與鬥爭中的許多卓越之處，以及其中一些卑劣的情感，都可以在西方這位城市之后的疆界內找到，她的腳下——當她眼中充滿北方的光芒坐著並沉思時——就是密西根湖的岸邊。", "st": "complete", "doubt": false}, {"id": "P14-15", "g": "preface", "pdf": "14-15", "book": null, "hi": "आधुनिक ज्ञान में ऐसा बहुत कम है, यूरोप के अतीत से उत्तराधिकार में प्राप्त ऐसा बहुत कम है, जिसकी कोई न कोई चौकी शिकागो की नगरी में न विद्यमान हो।", "rom": "Ādhunika jñāna mēṃ aisā bahuta kama hai, yūrōpa kē atīta sē uttarādhikāra mēṃ prāpta aisā bahuta kama hai, jisakī kōī na kōī caukī śikāgō kī nagarī mēṃ na vidyamāna hō.", "zh": "在現代知識中，幾乎沒有什麼東西；在從歐洲過去繼承而來的東西中，也幾乎沒有什麼東西，是在芝加哥這座城市裡沒有一個據點的。", "st": "complete", "doubt": false}, {"id": "P15-01", "g": "preface", "pdf": 15, "book": null, "hi": "और जहाँ हममें से कुछ को इस केन्द्र का जनसंकुल जीवन और अधीर-उत्सुकता अभी निरी विशृंखल ही क्यों न प्रतीत हों, फिर भी इसमें कोई संदेह नहीं कि वे मानवीय एकता के किसी महान् किन्तु धीरसंचारी आदर्श को उस समय व्यक्त करने की चेष्टा कर रहे हैं, जब उनकी परिपक्वता के दिन पूर्ण हो जायेंगे।", "rom": "Aura jahāṃ hamamēṃ sē kucha kō isa kēndra kā janasaṅkula jīvana aura adhīra-utsukatā abhī nirī viśṛṅkhala hī kyōṃ na pratīta hōṃ, phira bhī isamēṃ kōī sandēha nahīṃ ki vē mānavīya ēkatā kē kisī mahān kintu dhīrasañcārī ādarśa kō usa samaya vyakta karanē kī cēṣṭā kara rahē haiṃ, jaba unakī paripakvatā kē dina pūrṇa hō jāyēṃgē.", "zh": "而且，即使我們當中有些人覺得這個中心擁擠的生活與急切的熱情目前看起來全然散亂無序，仍毫無疑問，他們正在努力表達人類合一的某種偉大卻緩慢前行的理想，直到他們成熟的日子完全到來。", "st": "complete", "doubt": false}, {"id": "P15-02", "g": "preface", "pdf": 15, "book": null, "hi": "ऐसी मनोवैज्ञानिक भूमि थी, ऐसा मानस-सागर था—तरुण, तुमुल तथा अपनी शक्ति और आत्मविश्वास से उफनाता, फिर भी जिज्ञासु और जागरूक—जो भाषण आरम्भ करते समय विवेकानन्द के सम्मुख था।", "rom": "Aisī manōvaijñānika bhūmi thī, aisā mānasa-sāgara thā—taruṇa, tumula tathā apanī śakti aura ātmaviśvāsa sē uphanātā, phira bhī jijñāsu aura jāgarūka—jō bhāṣaṇa ārambha karatē samaya vivēkānanda kē sammukha thā.", "zh": "那是這樣一種心理土壤、一片這樣的心靈海洋——年輕、洶湧，並且因自己的力量與自信而翻騰，但仍好奇而警醒——在演說開始時出現在維韋卡南達面前。", "st": "complete", "doubt": false}, {"id": "P15-03", "g": "preface", "pdf": 15, "book": null, "hi": "इसके ठीक विपरीत, उनके पीछे युग युग के आध्यात्मिक विकास का प्रशान्त सागर था।", "rom": "Isakē ṭhīka viparīta, unakē pīchē yuga yuga kē ādhyātmika vikāsa kā praśānta sāgara thā.", "zh": "與此恰恰相反，在他身後，是世世代代精神發展的寧靜海洋。", "st": "complete", "doubt": false}, {"id": "P15-04", "g": "preface", "pdf": 15, "book": null, "hi": "उनके पीछे एक संसार था, जो अपनी काल-गणना वेदों से करता है और अपनी याद उपनिषदों में करता है—एक संसार, जिसकी तुलना में बौद्ध धर्म प्रायः आधुनिक है, एक संसार—मत-मतान्तरों की धार्मिक व्यवस्थाओं से पूर्ण, उष्ण कटिबन्ध की सूर्य-रश्मियों से स्नात शान्त देश, जिसकी सड़कों की रज पर युग-युगान्तर से संतों के चरण-चिह्न अंकित होते रहे थे।", "rom": "Unakē pīchē ēka saṃsāra thā, jō apanī kāla-gaṇanā vēdōṃ sē karatā hai aura apanī yāda upaniṣadōṃ mēṃ karatā hai—ēka saṃsāra, jisakī tulanā mēṃ bauddha dharma prāyaḥ ādhunika hai, ēka saṃsāra—mata-matāntarōṃ kī dhārmika vyavasthāōṃ sē pūrṇa, uṣṇa kaṭibandha kī sūrya-raśmiyōṃ sē snāta śānta dēśa, jisakī saṛakōṃ kī raja para yuga-yugāntara sē saṃtōṃ kē caraṇa-cihna aṅkita hōtē rahē thē.", "zh": "在他身後有一個世界，它用吠陀來計算時間，在奧義書中保存記憶——一個世界，與之相比，佛教幾乎是現代的；一個世界——充滿各宗各派的宗教體系，是一個沐浴在熱帶陽光下的寧靜國度，世世代代以來，聖人們的足跡一直印在它的道路塵土上。", "st": "complete", "doubt": false}, {"id": "P15-05", "g": "preface", "pdf": 15, "book": null, "hi": "संक्षेप में, उनके पीछे था वह भारत—सहस्रों वर्षों के अपने राष्ट्रीय विकास के साथ—जिसमें उसने अपने देश और काल के महान् विस्तार के एक छोर से दूसरे छोर तक अपने समस्त देशवासियों द्वारा सामान्य रूप से मान्यताप्राप्त कुछ मौलिक और सारभूत सत्यों का पता लगाया है, अनेक बातें सिद्ध की हैं, और केवल एक पूर्ण मतैक्य को छोड़कर, लगभग सबको उपलब्ध किया है।", "rom": "Saṅkṣēpa mēṃ, unakē pīchē thā vaha bhārata—sahasrōṃ varṣōṃ kē apanē rāṣṭrīya vikāsa kē sātha—jisamēṃ usanē apanē dēśa aura kāla kē mahān vistāra kē ēka chōra sē dūsarē chōra taka apanē samasta dēśavāsiyōṃ dvārā sāmānya rūpa sē mānyatāprāpta kucha maulika aura sārabhūta satyōṃ kā patā lagāyā hai, anēka bātēṃ siddha kī haiṃ, aura kēvala ēka pūrṇa mataikya kō chōṛakara, lagabhaga sabakō upalabdha kiyā hai.", "zh": "簡言之，在他身後的是那個印度——帶著數千年的民族發展——在其中，它從自己國土與時代的廣大範圍的一端到另一端，透過全體國民，普遍公認地發現了一些根本而實質的真理，證明了許多事情，並且除了完全的一致之外，幾乎一切都已獲得。", "st": "complete", "doubt": false}, {"id": "P15-06", "g": "preface", "pdf": 15, "book": null, "hi": "तो यही थे वे दो मानस-प्लावन, प्राच्य और अधुनातन चिन्तन के मानो दो प्रबल महानद।", "rom": "Tō yahī thē vē dō mānasa-plāvana, prācya aura adhunātana cintana kē mānō dō prabala mahānada.", "zh": "那麼，這就是那兩股心靈的洪流，彷彿是東方思想與現代思想的兩條強大江河。", "st": "complete", "doubt": false}, {"id": "P15-07", "g": "preface", "pdf": 15, "book": null, "hi": "धर्म-महासभा के रंगमंच पर विद्यमान गैरिक वसनमंडित यह परिब्राजक एक क्षण के निमित्त इन दोनों प्लावनों का संगम-बिन्दु बन गया।", "rom": "Dharma-mahāsabhā kē raṅgamañca para vidyamāna gairika vasanamaṇḍita yaha paribrājaka ēka kṣaṇa kē nimitta ina dōnōṃ plāvanōṃ kā saṅgama-bindu bana gayā.", "zh": "在宗教大會舞台上的這位身穿赭色袈裟的雲遊者，在一瞬間成為了這兩股洪流的匯合點。", "st": "complete", "doubt": false}, {"id": "P15-08", "g": "preface", "pdf": 15, "book": null, "hi": "हिन्दू धर्म के सामान्य आधारों का सूत्रीकरण इस परम नैर्व्यक्तिक व्यक्तित्व से उन प्लावनों के सम्पर्क के आघात का अपरिहार्य परिणाम था।", "rom": "Hindū dharma kē sāmānya ādhārōṃ kā sūtrīkaraṇa isa parama nairvyaktika vyaktitva sē una plāvanōṃ kē samparka kē āghāta kā aparihārya pariṇāma thā.", "zh": "印度教共同基礎的綱要化，是這位極為超個人的個體與那些洪流相遇衝擊的必然結果。", "st": "complete", "doubt": false}, {"id": "P15-09", "g": "preface", "pdf": 15, "book": null, "hi": "स्वामी विवेकानन्द के अधरों से जो शब्द उच्चरित हुए, वे स्वयं उनके अनुभवजनित नहीं थे।", "rom": "Svāmī vivēkānanda kē adharōṃ sē jō śabda uccarita huē, vē svayaṃ unakē anubhavajanita nahīṃ thē.", "zh": "從維韋卡南達唇間說出的那些話，並不是他自己經驗的產物。", "st": "complete", "doubt": false}, {"id": "P15-10", "g": "preface", "pdf": 15, "book": null, "hi": "न उन्होंने अपने गुरुदेव की कथा सुनाने के निमित्त ही इस अवसर का उपयोग किया।", "rom": "Na unhōṃnē apanē gurudēva kī kathā sunānē kē nimitta hī isa avasara kā upayōga kiyā.", "zh": "他也沒有僅僅為了講述自己上師的故事而利用這個機會。", "st": "complete", "doubt": false}, {"id": "P15-11", "g": "preface", "pdf": 15, "book": null, "hi": "इन दोनों के स्थान पर, भारत की धार्मिक चेतना—सम्पूर्ण अतीत द्वारा निर्धारित उनके समग्र देशवासियों का संदेश ही उनके माध्यम से मुखर हुआ था।", "rom": "Ina dōnōṃ kē sthāna para, bhārata kī dhārmika cētanā—sampūrṇa atīta dvārā nirdhārita unakē samagra dēśavāsiyōṃ kā sandēśa hī unakē mādhyama sē mukhara huā thā.", "zh": "取而代之的是，印度的宗教意識——由整個過去所決定的、他全體同胞的訊息——透過他而發出了聲音。", "st": "complete", "doubt": false}, {"id": "P15-12", "g": "preface", "pdf": "15-16", "book": null, "hi": "और जब वे पश्चिम के यौवन और मध्याह्न में बोल रहे थे, तब प्रशान्त के दूसरी ओर, तमसाच्छन्न गोलार्ध की छायाओं में प्रसुप्त एक राष्ट्र अपनी ओर गतिमान अरुणोदय के पंखों पर आनेवाली और उसके प्रति स्वयं उसके ही महत्त्व और शक्ति का रहस्य उद्घाटित करनेवाली वाणी की प्रतीक्षा अपनी आत्मा में कर रहा था।", "rom": "Aura jaba vē paścima kē yauvana aura madhyāhna mēṃ bōla rahē thē, taba praśānta kē dūsarī ōra, tamasācchanna gōlārdha kī chāyāōṃ mēṃ prasupta ēka rāṣṭra apanī ōra gatimāna aruṇōdaya kē paṅkhōṃ para ānēvālī aura usakē prati svayaṃ usakē hī mahattva aura śakti kā rahasya udghāṭita karanēvālī vāṇī kī pratīkṣā apanī ātmā mēṃ kara rahā thā.", "zh": "而當他在西方的青春與正午時分說話時，在太平洋的另一邊，一個在黑暗半球的陰影中沉睡的國家，正在自己的靈魂中等待著一種聲音——那聲音將乘著向它飛來的黎明的翅膀而來，並向它揭示它自身的重要與力量的奧祕。", "st": "complete", "doubt": false}, {"id": "P16-01", "g": "preface", "pdf": 16, "book": null, "hi": "उसी धर्म-महासभा के मंच पर स्वामी विवेकानन्द के अतिरिक्त विशिष्ट मतों और संघों के धर्मदूत भी उपस्थित थे।", "rom": "Usī dharma-mahāsabhā kē mañca para svāmī vivēkānanda kē atirikta viśiṣṭa matōṃ aura saṅghōṃ kē dharmadūta bhī upasthita thē.", "zh": "在同一個宗教大會的舞台上，除了維韋卡南達之外，各種特殊教派與團體的傳教士也都在場。", "st": "complete", "doubt": false}, {"id": "P16-02", "g": "preface", "pdf": 16, "book": null, "hi": "किन्तु एक ऐसे धर्म का प्रचार करने का गौरव उन्हींको था, जिस तक पहुँचने के लिए इनमें से प्रत्येक, उन्हींके शब्दों में, विविध अवस्थाओं और परिस्थितियों के द्वारा उसी एक लक्ष्य तक पहुँचने के निमित्त ‘विभिन्न स्त्री-पुरुषों की यात्रा, प्रगति मात्र है।’", "rom": "Kintu ēka aisē dharma kā pracāra karanē kā gaurava unhīṃkō thā, jisa taka pahuṃcanē kē liē inamēṃ sē pratyēka, unhīṃkē śabdōṃ mēṃ, vividha avasthāōṃ aura paristhitiyōṃ kē dvārā usī ēka lakṣya taka pahuṃcanē kē nimitta ‘vibhinna strī-puruṣōṃ kī yātrā, pragati mātra hai.’", "zh": "但宣揚這樣一種宗教的榮譽卻只屬於他——用他自己的話說，為了到達那種宗教，這裡的每一個人，透過種種階段與境遇，朝向同一個目標的旅程，不過是「男女眾生的行進、進步而已」。", "st": "complete", "doubt": false}, {"id": "P16-03", "g": "preface", "pdf": 16, "book": null, "hi": "और जैसा कि उन्होंने घोषित किया, वे वहाँ एक ऐसे महापुरुष का परिचय देने के लिए खड़े हुए थे, जिसने इन सभी मत-मतान्तरों के विषय में कहा है कि ऐसा नहीं है कि इनमें से कोई एक या दूसरा, इस या उस पक्ष में, इस या उस कारण, सत्य या असत्य है, वरन् मयि सर्वमिदं प्रोतं सूत्रे मणिगणा इव।", "rom": "Aura jaisā ki unhōṃnē ghōṣita kiyā, vē vahāṃ ēka aisē mahāpuruṣa kā paricaya dēnē kē liē khaṛē huē thē, jisanē ina sabhī mata-matāntarōṃ kē viṣaya mēṃ kahā hai ki aisā nahīṃ hai ki inamēṃ sē kōī ēka yā dūsarā, isa yā usa pakṣa mēṃ, isa yā usa kāraṇa, satya yā asatya hai, varan mayi sarvamidaṃ prōtaṃ sūtrē maṇigaṇā iva.", "zh": "而且，正如他所宣告的，他站在那裡，是要介紹一位偉人，關於所有這些宗派分歧，那位偉人說過：並不是其中某一個或另一個，在這一邊或那一邊，出於這個或那個原因，是真或假，而是「我身上串著這一切，如同線上的寶石群」。", "st": "complete", "doubt": false}, {"id": "P16-04", "g": "preface", "pdf": 16, "book": null, "hi": "‘यह सब सूत्र में मोतियों की भाँति मुझमें ही पुहे हुए हैं।’", "rom": "‘Yaha saba sūtra mēṃ mōtiyōṃ kī bhāṃti mujhamēṃ hī puhē huē haiṃ.’", "zh": "「這一切如同線上的珍珠，都穿在我身上。」", "st": "complete", "doubt": true}, {"id": "P16-05", "g": "preface", "pdf": 16, "book": null, "hi": "‘जहाँ मानव-जाति को पवित्र और उसका उन्नयन करती असामान्य पवित्रता, असामान्य शक्ति, तेरे देखने में आये, तू जान कि मैं वहीं हूँ।’", "rom": "‘Jahāṃ mānava-jāti kō pavitra aura usakā unnayana karatī asāmānya pavitratā, asāmānya śakti, tērē dēkhanē mēṃ āyē, tū jāna ki maiṃ vahīṃ hūṃ.’", "zh": "「凡是在你眼前出現能使人類聖潔並提升人類的非凡聖潔、非凡力量，你要知道，我就在那裡。」", "st": "complete", "doubt": false}, {"id": "P16-06", "g": "preface", "pdf": 16, "book": null, "hi": "विवेकानन्द का कहना है कि एक हिन्दू की दृष्टि में ‘मनुष्य भ्रम से सत्य की ओर नहीं जाता, वरन् सत्य से सत्य की ओर अग्रसर होता है; निम्नतर सत्य से उच्चतर सत्य की ओर जाता है।’", "rom": "Vivēkānanda kā kahanā hai ki ēka hindū kī dṛṣṭi mēṃ ‘manuṣya bhrama sē satya kī ōra nahīṃ jātā, varan satya sē satya kī ōra agrasara hōtā hai; nimnatara satya sē uccatara satya kī ōra jātā hai.’", "zh": "維韋卡南達說，在一位印度教徒看來，「人不是從錯誤走向真理，而是從真理走向真理；從較低的真理走向較高的真理。」", "st": "complete", "doubt": false}, {"id": "P16-07", "g": "preface", "pdf": 16, "book": null, "hi": "यह, तथा मुक्ति का यह सिद्धान्त कि ‘मनुष्य को ईश्वर का साक्षात्कार करके ईश्वर होना है’, यह सत्य कि धर्म केवल तभी हममें पूर्णता को प्राप्त करता है, जब वह हमें ‘उस तक ले जाता है, जो मृत्यु के संसार में एकमात्र जीवन है, उस तक जो नित्य परिवर्तनशील जगत् का चिरन्तन आधार है, उस-एक तक ले जाता है, जो केवल आत्मा ही है, अन्य सभी आत्माएँ जिसकी भ्रांत अभिव्यक्तियाँ मात्र हैं’—ये दो महान् विशिष्ट सत्यों के रूप में मान्य हो सकते हैं।", "rom": "Yaha, tathā mukti kā yaha siddhānta ki ‘manuṣya kō īśvara kā sākṣātkāra karakē īśvara hōnā hai’, yaha satya ki dharma kēvala tabhī hamamēṃ pūrṇatā kō prāpta karatā hai, jaba vaha hamēṃ ‘usa taka lē jātā hai, jō mṛtyu kē saṃsāra mēṃ ēkamātra jīvana hai, usa taka jō nitya parivartanaśīla jagat kā cirantana ādhāra hai, usa-ēka taka lē jātā hai, jō kēvala ātmā hī hai, anya sabhī ātmāēṃ jisakī bhrāṃta abhivyaktiyāṃ mātra haiṃ’—yē dō mahān viśiṣṭa satyōṃ kē rūpa mēṃ mānya hō sakatē haiṃ.", "zh": "這一點，以及解脫的這一原理——「人必須親證神而成為神」——以及這一真理：宗教只有在把我們帶到「那裡」時，才使我們達到圓滿——那裡是死亡世界中唯一的生命，是不斷變化的世界永恆的基礎，是那「一」，它只是靈魂本身，而其他一切靈魂都只是它的錯誤表現——這兩者可以被視為兩大獨特的真理。", "st": "complete", "doubt": false}, {"id": "P16-08", "g": "preface", "pdf": 16, "book": null, "hi": "भारत ने मानव-इतिहास की दीर्घतम और जटिलतम अनुभूति के द्वारा प्रमाणीकृत इन दोनों सत्यों को उनके माध्यम से पश्चिम के आधुनिक जगत् में घोषित किया।", "rom": "Bhārata nē mānava-itihāsa kī dīrghatama aura jaṭilatama anubhūti kē dvārā pramāṇīkṛta ina dōnōṃ satyōṃ kō unakē mādhyama sē paścima kē ādhunika jagat mēṃ ghōṣita kiyā.", "zh": "印度透過他，向西方的現代世界宣告了這兩項真理——這兩項真理已由人類歷史最悠久、最複雜的經驗所證實。", "st": "complete", "doubt": false}, {"id": "P16-09", "g": "preface", "pdf": 16, "book": null, "hi": "स्वयं भारत के लिए, जैसा पहले ही कहा जा चुका है, यह संक्षिप्त अभिभाषण मताधिकार की एक छोटी सी सनद थी।", "rom": "Svayaṃ bhārata kē liē, jaisā pahalē hī kahā jā cukā hai, yaha saṅkṣipta abhibhāṣaṇa matādhikāra kī ēka chōṭī sī sanada thī.", "zh": "就印度本身而言，如前所述，這篇簡短的演說是一份小小的意見權利證書。", "st": "complete", "doubt": false}, {"id": "P16-10", "g": "preface", "pdf": 16, "book": null, "hi": "वक्ता ने हिन्दू धर्म को सर्वगितया वेदों पर आधारित किया है; किन्तु वेद सम्बन्धी हमारी धारणा का वे इस शब्द के उच्चारण मात्र से ही आध्यात्मीकरण कर देते हैं।", "rom": "Vaktā nē hindū dharma kō sarvagitayā vēdōṃ para ādhārita kiyā hai; kintu vēda sambandhī hamārī dhāraṇā kā vē isa śabda kē uccāraṇa mātra sē hī ādhyātmīkaraṇa kara dētē haiṃ.", "zh": "演說者把印度教建立在吠陀之上（原文用詞照錄）；但僅憑說出這個詞，他就把我們關於吠陀的觀念予以精神化。", "st": "complete", "doubt": true}, {"id": "P16-11", "g": "preface", "pdf": 16, "book": null, "hi": "उनके निकट, जो कुछ सत्य है, वह सब वेद है।", "rom": "Unakē nikaṭa, jō kucha satya hai, vaha saba vēda hai.", "zh": "在他看來，凡是真實的，一切都是吠陀。", "st": "complete", "doubt": false}, {"id": "P16-12a", "g": "preface", "pdf": 16, "book": null, "hi": "वे कहते हैं, “वेदों का अर्थ कोई ग्रंथ नहीं है।", "rom": "Vē kahatē haiṃ, “Vēdōṃ kā artha kōī graṃtha nahīṃ hai.", "zh": "他說：「吠陀的意思不是任何一本書。」", "st": "complete", "doubt": false}, {"id": "P17-01", "g": "preface", "pdf": "16-17", "book": null, "hi": "वेदों का अर्थ है, विविध समयों पर विविध व्यक्तियों द्वारा आविष्कृत आध्यात्मिक नियमों का संचित कोष।’", "rom": "Vēdōṃ kā artha hai, vividha samayōṃ para vividha vyaktiyōṃ dvārā āviṣkṛta ādhyātmika niyamōṃ kā saṃcita kōṣa.’", "zh": "吠陀的意義是，在不同時代由不同的人所揭示的靈性法則的積累寶庫。」", "st": "complete", "doubt": false}, {"id": "P17-02", "g": "preface", "pdf": 17, "book": null, "hi": "प्रसंगवश वे सनातन धर्म के समन्वय में अपने विचार को भी प्रकट करते हैं।", "rom": "Prasaṃgavaśa vē sanātana dharma kē samanvaya mēṃ apanē vicāra kō bhī prakaṭa karatē haiṃ.", "zh": "順帶一提，他對於永恆法（印度教）的綜合，也表達了自己的看法。", "st": "complete", "doubt": false}, {"id": "P17-03", "g": "preface", "pdf": 17, "book": null, "hi": "‘विज्ञान की नूतनतम खोजें जिसकी प्रतिध्वनि जैसी लगती हैं, उस वेदान्त दर्शन के उच्च आध्यात्मिक स्तरों से लेकर, विविधतामय पौराणिकतायुक्त मूर्ति-पूजा के निम्नतम विचार, बौद्धों के अज्ञेयवाद और जैनों के निरीश्वरवाद तक प्रत्येक और सबका स्थान हिन्दू धर्म में है।’", "rom": "‘Vijñāna kī nūtanatama khōjēṃ jisakī pratidhvani jaisī lagatī haiṃ, usa vēdānta darśana kē ucca ādhyātmika starōṃ sē lēkara, vividhatāmaya paurāṇikatāyukta mūrti-pūjā kē nimnatama vicāra, bauddhōṃ kē ajñēyavāda aura jainōṃ kē nirīśvaravāda taka pratyēka aura sabakā sthāna hindū dharma mēṃ hai.’", "zh": "「科學最新發現彷彿只是其迴響的吠檀多哲學，從最高的靈性層次，一直到多樣的神話性偶像崇拜的最低觀念、佛教的不可知論、耆那教的無神論，每一種與全部，在印度教中都有其位置。」", "st": "complete", "doubt": false}, {"id": "P17-04", "g": "preface", "pdf": 17, "book": null, "hi": "उनकी दृष्टि में भारतवासियों का कोई भी मत, संप्रदाय अथवा कोई भी सच्ची धर्मानुभूति—वह किसीको कितनी ही धूमिल क्यों न प्रतीत हो—ऐसी नहीं है, जिसे हिन्दू धर्म की बाहुओं से औचित्यपूर्वक बहिष्कृत किया जा सके।", "rom": "Unakī dṛṣṭi mēṃ bhāratavāsiyōṃ kā kōī bhī mata, saṃpradāya athavā kōī bhī saccī dharmānubhūti—vaha kisīkō kitanī hī dhūmila kyōṃ na pratīta hō—aisī nahīṃ hai, jisē hindū dharma kī bāhuōṃ sē aucityapūrvaka bahiṣkṛta kiyā jā sakē.", "zh": "在他看來，印度人的任何一種見解、教派，或者任何一種真實的宗教體驗——不論它看起來多麼模糊——都不是可以正當地被逐出印度教懷抱的。", "st": "complete", "doubt": false}, {"id": "P17-05", "g": "preface", "pdf": 17, "book": null, "hi": "और उनके अनुसार इस भारतीय धर्म-माता का विशिष्ट सिद्धान्त है इष्ट देवता—हर आत्मा को अपने मार्ग को चुनने तथा ईश्वर को अपने ढंग से खोजने का अधिकार।", "rom": "Aura unakē anusāra isa bhāratīya dharma-mātā kā viśiṣṭa siddhānta hai iṣṭa dēvatā—hara ātmā kō apanē mārga kō cunanē tathā īśvara kō apanē ḍhaṃga sē khōjanē kā adhikāra.", "zh": "而在他看來，這位印度宗教之母的獨特原理是所崇敬的神——每個靈魂都有權選擇自己的道路、並以自己的方式尋求神。", "st": "complete", "doubt": false}, {"id": "P17-06", "g": "preface", "pdf": 17, "book": null, "hi": "अतः इस प्रकार से परिभाषित हिन्दू धर्म के बराबर विराट् साम्राज्य की पताका का वहन कोई अन्य वाहिनी नहीं करती; क्योंकि जिस प्रकार ईश्वर की प्राप्ति इसका आध्यात्मिक लक्ष्य है, उसी प्रकार इसका आध्यात्मिक नियम है, प्रत्येक आत्मा की स्वस्वरूप में प्रतिष्ठित होने की पूर्ण स्वतंत्रता।", "rom": "Ataḥ isa prakāra sē paribhāṣita hindū dharma kē barābara virāṭ sāmrājya kī patākā kā vahana kōī anya vāhinī nahīṃ karatī; kyōṃki jisa prakāra īśvara kī prāpti isakā ādhyātmika lakṣya hai, usī prakāra isakā ādhyātmika niyama hai, pratyēka ātmā kī svasvarūpa mēṃ pratiṣṭhita hōnē kī pūrṇa svatantratā.", "zh": "因此，沒有任何其他力量能像這樣被定義的印度教一樣，擎起如此浩大帝國的旗幟；因為正如獲得神是它的靈性目標一樣，它的靈性法則也是：每個靈魂在自己的本性中安立的完全自由。", "st": "complete", "doubt": false}, {"id": "P17-07", "g": "preface", "pdf": 17, "book": null, "hi": "किन्तु सर्वों का यह समावेश, प्रत्येक की यह स्वतंत्रता हिन्दू धर्म की ऐसी गरिमा न बन पाती, यदि उसका परम आह्वान और उसकी मधुरतम प्रतिज्ञा यह न होती : ‘हे अमृतपुत्रो !", "rom": "Kintu sarvōṃ kā yaha samāvēśa, pratyēka kī yaha svatantratā hindū dharma kī aisī garimā na bana pātī, yadi usakā parama āhvāna aura usakī madhuratama pratijñā yaha na hōtī : ‘Hē amṛtaputrō !", "zh": "但是，這種包容一切、每個人都自由的情況，若不是因為它最高的召喚與最甘美的承諾，就不會成為印度教的這種尊嚴：「啊，不死之子們！", "st": "complete", "doubt": false}, {"id": "P17-08", "g": "preface", "pdf": 17, "book": null, "hi": "सुनो !", "rom": "Sunō !", "zh": "聽啊！", "st": "complete", "doubt": false}, {"id": "P17-09", "g": "preface", "pdf": 17, "book": null, "hi": "उच्चतर लोकों में रहनेवालो, तुम भी सुनो : मैंने उस पुराण पुरुष को पा लिया है, जो समस्त अंधकार, समस्त भ्रांति के परे है।", "rom": "Uccatara lōkōṃ mēṃ rahanēvālō, tuma bhī sunō : mainnē usa purāṇa puruṣa kō pā liyā hai, jō samasta aṃdhakāra, samasta bhrānti kē parē hai.", "zh": "住在更高世界的人們，你們也聽啊：我已經找到了那位古老的人，他超越一切黑暗、一切迷惑。", "st": "complete", "doubt": false}, {"id": "P17-10", "g": "preface", "pdf": 17, "book": null, "hi": "और तुम भी उसको जानकर मृत्यु से मुक्ति प्राप्त कर सकोगे।’", "rom": "Aura tuma bhī usakō jānakara mṛtyu sē mukti prāpta kara sakōgē.’", "zh": "而你們認識了他，也能從死亡中獲得解脫。」", "st": "complete", "doubt": false}, {"id": "P17-11", "g": "preface", "pdf": 17, "book": null, "hi": "यही है वह शब्द, जिसके निमित्त शेष सबका अस्तित्व है और रहा है।", "rom": "Yahī hai vaha śabda, jisakē nimitta śēṣa sabakā astitva hai aura rahā hai.", "zh": "這就是那個話語，為了它，其餘一切的存在才存在、並且一直存在。", "st": "complete", "doubt": false}, {"id": "P17-12", "g": "preface", "pdf": 17, "book": null, "hi": "इसीमें वह चरम अनुभूति है, जिसमें अन्य सबका तिरोभाव हो जाता है।", "rom": "Isīmēṃ vaha carama anubhūti hai, jismēṃ anya sabakā tirōbhāva hō jātā hai.", "zh": "在其中就是那最高的體驗，在其中其他一切都消失了。", "st": "complete", "doubt": false}, {"id": "P17-13", "g": "preface", "pdf": "17-18", "book": null, "hi": "जब ‘हमारा प्रस्तुत कार्य’ नामक अपने व्याख्यान में स्वामी जी सबको यह शपथ दिलाते हैं कि वे उनकी सहायता एक ऐसे मंदिर का निर्माण करने में करें, जहाँ देश का प्रत्येक उपासक उपासना कर सके, एक ऐसा, जिसके गर्भगृह में केवल ॐ शब्द मात्र होगा, तो हममें से कुछ को उनके इस वचन में एक इससे भी महान् मंदिर की झलक मिलती है—स्वयं भारत की, मातृभूमि की, जैसी कि वह है—और हम केवल भारतीय धर्मों के ही नहीं, वरन् समग्र मानव-जाति के विभिन्न भागों को वहाँ केन्द्रित होते देखते हैं, उस पुनीत स्थल के चरणों में जहाँ वह प्रतीक प्रतिष्ठित है, जो प्रतीक है ही नहीं, जहाँ वह नाम है, जो ध्वनि मात्र के अतीत है।", "rom": "Jaba ‘hamārā prastuta kārya’ nāmaka apanē vyākhyāna mēṃ svāmī jī sabakō yaha śapatha dilātē haiṃ ki vē unakī sahāyatā ēka aisē maṃdira kā nirmāṇa karanē mēṃ karēṃ, jahāṃ dēśa kā pratyēka upāsaka upāsanā kara sakē, ēka aisā, jisakē garbhagṛha mēṃ kēvala ōṃ śabda mātra hōgā, tō hamamēṃ sē kucha kō unakē isa vacana mēṃ ēka isasē bhī mahān maṃdira kī jhalaka milatī hai—svayaṃ bhārata kī, mātṛbhūmi kī, jaisī ki vaha hai—aura hama kēvala bhāratīya dharmōṃ kē hī nahīṃ, varan samagra mānava-jāti kē vibhinna bhāgōṃ kō vahāṃ kēndrita hōtē dēkhatē haiṃ, usa punīta sthala kē caraṇōṃ mēṃ jahāṃ vaha pratīka pratiṣṭhita hai, jō pratīka hai hī nahīṃ, jahāṃ vaha nāma hai, jō dhvani mātra kē atīta hai.", "zh": "當維韋卡南達在題為「我們當前的工作」的演講中，要大家發誓幫助他建造這樣一座寺廟——在那裡全國的每一位崇拜者都能崇拜，一座其內殿中只有唵（Om）這個詞的寺廟——我們當中有些人便在他這番話中，看見了一座比這更偉大的寺廟的閃光——印度本身、祖國本身，如其所是——而我們看見的不僅是印度的各宗教，而且是全人類的各個部分，都集中在那個神聖處所的腳下，在那裡安立著那個其實不是象徵的象徵，在那裡有那個僅僅超越聲音的名字。", "st": "complete", "doubt": false}, {"id": "P18-01", "g": "preface", "pdf": 18, "book": null, "hi": "सभी उपासनाओं के समस्त मार्ग और सभी धर्म इसी ओर पहुँचाते हैं, इससे भिन्न दिशा में नहीं।", "rom": "Sabhī upāsanāōṃ kē samasta mārga aura sabhī dharma isī ōra pahum̐cātē haiṃ, isasē bhinna diśā mēṃ nahīṃ.", "zh": "一切崇拜的全部道路與一切宗教，都通向這個方向，而不是相反的方向。", "st": "complete", "doubt": false}, {"id": "P18-02", "g": "preface", "pdf": 18, "book": null, "hi": "भारत अपनी इस घोषणा में विश्व के परम विशुद्धतावादी धर्मों के साथ है कि प्रगति दृश्य से अदृश्य की ओर, अनेक से एक की ओर, निम्न से उच्च की ओर, साकार से निराकार की ओर होती है, किन्तु विपरीत दिशा में कदापि नहीं।", "rom": "Bhārata apanī isa ghōṣaṇā mēṃ viśva kē parama viśuddhatāvādī dharmōṃ kē sātha hai ki pragati dṛśya sē adṛśya kī ōra, anēka sē ēka kī ōra, nimna sē ucca kī ōra, sākāra sē nirākāra kī ōra hōtī hai, kintu viparīta diśā mēṃ kadāpi nahīṃ.", "zh": "印度在這一宣告上與世界最純粹主義的宗教站在一起：進步是從可見走向不可見、從多走向一、從低走向高、從有形走向無形，絕不是相反的方向。", "st": "complete", "doubt": false}, {"id": "P18-03", "g": "preface", "pdf": 18, "book": null, "hi": "भारत के साथ अंतर केवल इतना है कि वह हर सच्ची अवस्था को—वह जो भी हो, और जहाँ भी हो—उस महान् आरोहण का एक सोपान मानकर उसको सहानुभूति और आश्वासन प्रदान करता है।", "rom": "Bhārata kē sātha aṃtara kēvala itanā hai ki vaha hara saccī avasthā kō—vaha jō bhī hō, aura jahāṃ bhī hō—usa mahān ārōhaṇa kā ēka sōpāna mānakara usakō sahānubhūti aura āśvāsana pradāna karatā hai.", "zh": "與印度不同之處僅在於：它把每一個真實的階段——不論是什麼、不論在哪裡——都當作那偉大上升的一個階梯，給予它同情與安慰。", "st": "complete", "doubt": false}, {"id": "P18-04", "g": "preface", "pdf": 18, "book": null, "hi": "यदि हिन्दू धर्म के दूत के रूप में उनका कुछ अपना होता, तो स्वामी विवेकानन्द, जो कुछ थे, उससे कम महान् सिद्ध हुए होते।", "rom": "Yadi hindū dharma kē dūta kē rūpa mēṃ unakā kucha apanā hōtā, tō svāmī vivēkānanda, jō kucha thē, usasē kama mahān siddha huē hōtē.", "zh": "如果作為印度教的使者，他有什麼是自己獨有的，那麼維韋卡南達就會被證明比他實際上更不偉大。", "st": "complete", "doubt": false}, {"id": "P18-05", "g": "preface", "pdf": 18, "book": null, "hi": "गीता के कृष्ण की भाँति, बुद्ध की भाँति, शंकराचार्य की भाँति, भारतीय चिंतन के अन्य प्रत्येक महान् विचारक की भाँति, उनके वाक्य भी वेदों और उपनिषदों के उद्धरणों से परिपूर्ण हैं।", "rom": "Gītā kē kṛṣṇa kī bhāṃti, buddha kī bhāṃti, śaṃkarācārya kī bhāṃti, bhāratīya ciṃtana kē anya pratyēka mahān vicāraka kī bhāṃti, unakē vākya bhī vēdōṃ aura upaniṣadōṃ kē uddharaṇōṃ sē paripūrṇa haiṃ.", "zh": "如同《薄伽梵歌》中的克里希納、如同佛陀、如同商羯羅阿闍梨、如同印度思想的其他每一位偉大思想家一樣，他的話語也充滿了吠陀與奧義書的引文。", "st": "complete", "doubt": false}, {"id": "P18-06", "g": "preface", "pdf": 18, "book": null, "hi": "भारत के पास जो अपनी ही निधियाँ सुरक्षित हैं, भारत के ही प्रति उनके मात्र उद्घाटक और भाष्यकार के रूप में ही स्वामी जी का महत्त्व है।", "rom": "Bhārata kē pāsa jō apanī hī nidhiyāṃ surakṣita haiṃ, bhārata kē hī prati unakē mātra udghaṭaka aura bhāṣyakāra kē rūpa mēṃ hī svāmī jī kā mahattva hai.", "zh": "印度自己所保存的寶藏，維韋卡南達的重要性僅在於：他只是向印度本身揭示並詮釋這些寶藏的人。", "st": "complete", "doubt": false}, {"id": "P18-07", "g": "preface", "pdf": 18, "book": null, "hi": "यदि वे कभी जन्म ही न लेते, तो भी जिन सत्यों का उपदेश उन्होंने किया, वे वैसे सत्य बने रहते।", "rom": "Yadi vē kabhī janma hī na lētē, tō bhī jina satyōṃ kā upadēśa unhōṃnē kiyā, vē vaisē satya banē rahatē.", "zh": "即使他從未出生，他所教導的那些真理，仍然會是同樣的真理。", "st": "complete", "doubt": false}, {"id": "P18-08", "g": "preface", "pdf": 18, "book": null, "hi": "यही नहीं, वे सत्य उतने ही प्रामाणिक भी बने रहते।", "rom": "Yahī nahīṃ, vē satya utanē hī prāmāṇika bhī banē rahatē.", "zh": "不僅如此，那些真理也同樣具有權威性。", "st": "complete", "doubt": false}, {"id": "P18-09", "g": "preface", "pdf": 18, "book": null, "hi": "अंतर केवल होता, उनकी प्राप्ति की कठिनाई में, उनकी अभिव्यक्ति में आधुनिक स्पष्टता और तीक्ष्णता के अभाव में और उनके पारस्परिक सामंजस्य एवं एकता की हानि में।", "rom": "Aṃtara kēvala hōtā, unakī prāpti kī kaṭhināī mēṃ, unakī abhivyakti mēṃ ādhunika spaṣṭatā aura tīkṣṇatā kē abhāva mēṃ aura unakē pārasparika sāmaṃjasya ēvaṃ ēkatā kī hāni mēṃ.", "zh": "差別只會在於：要獲得它們會更困難，它們的表達會缺乏現代的清晰與銳利，並且它們彼此的和諧與統一會受損。", "st": "complete", "doubt": false}, {"id": "P18-10", "g": "preface", "pdf": 18, "book": null, "hi": "यदि वे न होते, तो आज सहस्रों लोगों को जीवनदायी संदेश प्रदान करनेवाले वे ग्रंथ पंडितों के विवाद के विषय ही बने रह जाते।", "rom": "Yadi vē na hōtē, tō āja sahasrōṃ lōgōṃ kō jīvanadāyī saṃdēśa pradāna karanēvālē vē graṃtha paṇḍitōṃ kē vivāda kē viṣaya hī banē raha jātē.", "zh": "如果沒有他，今天向成千上萬人傳遞賦予生命訊息的那些典籍，就只會停留在學者爭論的題目上。", "st": "complete", "doubt": false}, {"id": "P18-11", "g": "preface", "pdf": 18, "book": null, "hi": "उन्होंने एक पंडित की भाँति नहीं, एक अधिकारी व्यक्ति की भाँति उपदेश दिया।", "rom": "Unhōṃnē ēka paṇḍita kī bhāṃti nahīṃ, ēka adhikārī vyakti kī bhāṃti upadēśa diyā.", "zh": "他不是像一位學者那樣教導，而是像一位有權威的人那樣教導。", "st": "complete", "doubt": false}, {"id": "P18-12", "g": "preface", "pdf": 18, "book": null, "hi": "क्योंकि जिस सत्यानुभूति का उपदेश उन्होंने किया, उसकी गहराइयों में वे स्वयं ही गोता लगा चुके थे और रामानुज की भाँति उसके रहस्यों को चांडाल, जाति-बहिष्कृत और विदेशियों को बतलाने के निमित्त ही वे वहाँ से लौटे थे।", "rom": "Kyōṃki jisa satyānubhūti kā upadēśa unhōṃnē kiyā, usakī gaharāiyōṃ mēṃ vē svayaṃ hī gōtā lagā cukē thē aura rāmānuja kī bhāṃti usakē rahasyōṃ kō cāṇḍāla, jāti-bahiṣkṛta aura vidēśiyōṃ kō batalānē kē nimitta hī vē vahāṃ sē lauṭē thē.", "zh": "因為他所教導的那種真理體驗，他自己早已潛入其深處；並且如同羅摩奴闍一樣，他正是為了把其中的奧祕告訴旃陀羅、被種姓逐出者與外國人，才從那裡回來的。", "st": "complete", "doubt": false}, {"id": "P18-13", "g": "preface", "pdf": 18, "book": null, "hi": "किन्तु फिर भी यह कथन कि उनके उपदेशों में कुछ नवीनता नहीं है, पूर्णतः सत्य नहीं है।", "rom": "Kintu phira bhī yaha kathana ki unakē upadēśōṃ mēṃ kucha navīnatā nahīṃ hai, pūrṇataḥ satya nahīṃ hai.", "zh": "但是，說他的教導中沒有一點新意，這句話仍然不完全是真的。", "st": "complete", "doubt": false}, {"id": "P18-14", "g": "preface", "pdf": "18-19", "book": null, "hi": "यह कभी नहीं भूलना चाहिए कि ये स्वामी विवेकानन्द ही थे, जिन्होंने अद्वैत दर्शन के श्रेष्ठत्व की घोषणा करते हुए कहा था कि इस अद्वैत में यह अनुभूति समाविष्ट है, जिसमें सब एक हैं, जो एकमेवाद्वितीय है; पर साथ साथ उन्होंने हिन्दू धर्म में यह सिद्धान्त भी संयोजित किया कि द्वैत, विशिष्टाद्वैत और अद्वैत एक ही विकास के तीन सोपान या स्तर हैं, जिनमें अंतिम अद्वैत ही लक्ष्य है।", "rom": "Yaha kabhī nahīṃ bhūlanā cāhiē ki yē svāmī vivēkānanda hī thē, jinhōṃnē advaita darśana kē śrēṣṭhatva kī ghōṣaṇā karatē huē kahā thā ki isa advaita mēṃ yaha anubhūti samāviṣṭa hai, jismēṃ saba ēka haiṃ, jō ēkamēvādvitīya hai; para sātha sātha unhōṃnē hindū dharma mēṃ yaha siddhānta bhī saṃyōjita kiyā ki dvaita, viśiṣṭādvaita aura advaita ēka hī vikāsa kē tīna sōpāna yā stara haiṃ, jinamēṃ aṃtima advaita hī lakṣya hai.", "zh": "絕不應忘記，正是維韋卡南達，在宣告不二哲學的卓越時說過：在不二之中包含著這樣的體驗，其中一切都是一，那是「唯一無二」；但同時，他也在印度教中加入了這一原理：二元、限定不二與不二，是同一個發展的三個階梯或層次，其中最終的不二就是目標。", "st": "complete", "doubt": false}, {"id": "P19-01", "g": "preface", "pdf": 19, "book": null, "hi": "यह एक और भी महान् तथा अधिक सरल, इस सिद्धान्त का अंग है कि अनेक और एक, विभिन्न समयों पर विभिन्न वृत्तियों में मन के द्वारा देखे जानेवाला एक ही तत्त्व है; अथवा जैसा श्री रामकृष्ण ने उसी सत्य को इस प्रकार व्यक्त किया है, “ईश्वर साकार और निराकार, दोनों ही है।", "rom": "Yaha ēka aura bhī mahān tathā adhika sarala, isa siddhānta kā aṃga hai ki anēka aura ēka, vibhinna samayōṃ para vibhinna vṛttiyōṃ mēṃ mana kē dvārā dēkhē jānēvālā ēka hī tattva hai; athavā jaisā śrī rāmakṛṣṇa nē usī satya kō isa prakāra vyakta kiyā hai, “Īśvara sākāra aura nirākāra, dōnōṃ hī hai.", "zh": "這也是這一原理中更偉大、也更簡單的一部分：多與一，是在不同時間、不同心境中被心所看見的同一個本質；或者，如同羅摩克里希納以這樣的方式表達了同一個真理：「神既是有形也是無形的。", "st": "complete", "doubt": false}, {"id": "P19-02", "g": "preface", "pdf": 19, "book": null, "hi": "ईश्वर वह भी है, जिसमें साकार और निराकार, दोनों ही समाविष्ट हैं।”", "rom": "Īśvara vaha bhī hai, jismēṃ sākāra aura nirākāra, dōnōṃ hī samāviṣṭa haiṃ.”", "zh": "神也是那一位，在他裡面有形與無形兩者都包含在內。」", "st": "complete", "doubt": false}, {"id": "P19-03", "g": "preface", "pdf": 19, "book": null, "hi": "यही—वह वस्तु है, जो हमारे गुरुदेव के जीवन को सर्वोच्च महत्त्व प्रदान करती है, क्योंकि यहाँ वे पूर्व और पश्चिम के ही नहीं, भूत और भविष्य के भी संगम-बिन्दु बन जाते हैं।", "rom": "Yahī—vaha vastu hai, jō hamārē gurudēva kē jīvana kō sarvōcca mahattva pradāna karatī hai, kyōṃki yahāṃ vē pūrva aura paścima kē hī nahīṃ, bhūta aura bhaviṣya kē bhī saṃgama-bindu bana jātē haiṃ.", "zh": "這——就是賦予我們上師一生最高意義的東西，因為在這裡，他不僅成為東方與西方的交會點，也成為過去與未來的交會點。", "st": "complete", "doubt": false}, {"id": "P19-04", "g": "preface", "pdf": 19, "book": null, "hi": "यदि एक और अनेक सचमुच एक ही सत्य हैं, तो केवल उपासना के ही विविध प्रकार नहीं, वरन् सामान्य रूप से कर्म के भी सभी प्रकार, संघर्ष के सभी प्रकार, सर्जन के सभी प्रकार भी, सत्य-साक्षात्कार के मार्ग हैं।", "rom": "Yadi ēka aura anēka sacamuca ēka hī satya haiṃ, tō kēvala upāsanā kē hī vividha prakāra nahīṃ, varan sāmānya rūpa sē karma kē bhī sabhī prakāra, saṃgharṣa kē sabhī prakāra, sarjana kē sabhī prakāra bhī, satya-sākṣātkāra kē mārga haiṃ.", "zh": "如果一與多確實是同一個真理，那麼不僅是崇拜的各種方式，一般而言，行動的各種方式、奮鬥的各種方式、創造的各種方式，也都是親證真理的道路。", "st": "complete", "doubt": false}, {"id": "P19-05", "g": "preface", "pdf": 19, "book": null, "hi": "अतः लौकिक और धार्मिक में अब आगे कोई भेद नहीं रह जाता।", "rom": "Ataḥ laukika aura dhārmika mēṃ aba āgē kōī bhēda nahīṃ raha jātā.", "zh": "因此，世俗與宗教之間，從此不再有任何區別。", "st": "complete", "doubt": false}, {"id": "P19-06", "g": "preface", "pdf": 19, "book": null, "hi": "कर्म करना ही उपासना करना है।", "rom": "Karma karanā hī upāsanā karanā hai.", "zh": "行動本身就是崇拜。", "st": "complete", "doubt": false}, {"id": "P19-07", "g": "preface", "pdf": 19, "book": null, "hi": "विजय प्राप्त करना ही त्याग करना है।", "rom": "Vijaya prāpta karanā hī tyāga karanā hai.", "zh": "獲得勝利本身就是捨棄。", "st": "complete", "doubt": false}, {"id": "P19-08", "g": "preface", "pdf": 19, "book": null, "hi": "स्वयं जीवन ही धर्म है।", "rom": "Svayaṃ jīvana hī dharma hai.", "zh": "生命本身就是宗教。", "st": "complete", "doubt": false}, {"id": "P19-09", "g": "preface", "pdf": 19, "book": null, "hi": "प्राप्त करना और अपने अधिकार में रखना उतना ही कठोर न्याय है, जितना कि त्याग करना और विमुख होना।", "rom": "Prāpta karanā aura apanē adhikāra mēṃ rakhanā utanā hī kaṭhōra nyāya hai, jitanā ki tyāga karanā aura vimukha hōnā.", "zh": "獲得並掌握在自己手裡，與捨棄並轉身離開一樣，都是同樣嚴格的正義。", "st": "complete", "doubt": false}, {"id": "P19-10", "g": "preface", "pdf": 19, "book": null, "hi": "स्वामी विवेकानन्द की यही अनुभूति है, जिसने उन्हें उस कर्म का महान् उपदेष्टा सिद्ध किया, जो ज्ञान-भक्ति से अलग नहीं, वरन् उन्हें अभिव्यक्त करनेवाला है।", "rom": "Svāmī vivēkānanda kī yahī anubhūti hai, jisanē unhēṃ usa karma kā mahān upadēṣṭā siddha kiyā, jō jñāna-bhakti sē alaga nahīṃ, varan unhēṃ abhivyakta karanēvālā hai.", "zh": "正是維韋卡南達的這種體驗，使他成為那種行動的偉大導師；那種行動與知識、虔信並不分離，而是表現它們的行動。", "st": "complete", "doubt": false}, {"id": "P19-11", "g": "preface", "pdf": 19, "book": null, "hi": "उनके लिए कारखाना, अध्ययन-कक्ष, खेत और क्रीड़ाभूमि आदि भगवान् के साक्षात्कार के वैसे ही उत्तम और योग्य स्थान हैं, जैसे साधु की कुटी या मन्दिर का द्वार।", "rom": "Unakē liē kārakhānā, adhyayana-kakṣa, khēta aura krīḍābhūmi ādi bhagavān kē sākṣātkāra kē vaisē hī uttama aura yōgya sthāna haiṃ, jaisē sādhu kī kuṭī yā mandira kā dvāra.", "zh": "對他而言，工廠、書房、田野與運動場等等，都是親見神的同樣優良、合適的場所，就像聖者的茅屋或寺廟的門口一樣。", "st": "complete", "doubt": false}, {"id": "P19-12", "g": "preface", "pdf": 19, "book": null, "hi": "उनके लिए मानव की सेवा और ईश्वर की पूजा, पौरुष तथा श्रद्धा, सच्चे नैतिक बल और आध्यात्मिकता में कोई अन्तर नहीं है।", "rom": "Unakē liē mānava kī sēvā aura īśvara kī pūjā, pauruṣa tathā śraddhā, saccē naitika bala aura ādhyātmikatā mēṃ kōī antara nahīṃ hai.", "zh": "對他而言，服務人類與崇拜神、勇氣與信仰、真正的道德力量與靈性之間，沒有任何區別。", "st": "complete", "doubt": false}, {"id": "P19-13", "g": "preface", "pdf": 19, "book": null, "hi": "एक दृष्टि से उनकी सम्पूर्ण वाणी को इसी केन्द्रीय दृढ़ आत्मा के भाष्य के रूप में पढ़ा जा सकता है।", "rom": "Ēka dṛṣṭi sē unakī sampūrṇa vāṇī kō isī kēndrīya dṛḍha ātmā kē bhāṣya kē rūpa mēṃ paṛhā jā sakatā hai.", "zh": "從一個角度看，他的全部言說都可以被讀作對這個堅定中心自我的詮釋。", "st": "complete", "doubt": false}, {"id": "P19-14", "g": "preface", "pdf": 19, "book": null, "hi": "एक बार उन्होंने कहा था, “कला, विज्ञान एवं धर्म एक ही सत्य की अभिव्यक्ति के विविध माध्यम हैं।", "rom": "Ēka bāra unhōṃnē kahā thā, “Kalā, vijñāna ēvaṃ dharma ēka hī satya kī abhivyakti kē vividha mādhyama haiṃ.", "zh": "有一次他曾說過：「藝術、科學與宗教是同一真理表現的不同媒介。", "st": "complete", "doubt": false}, {"id": "P19-15", "g": "preface", "pdf": 19, "book": null, "hi": "लेकिन इसे समझने के लिए निश्चय ही हमें अद्वैत का सिद्धान्त चाहिए।”", "rom": "Lēkina isē samajhanē kē liē niścaya hī hamēṃ advaita kā siddhānta cāhiē.”", "zh": "但是要理解這一點，我們肯定需要不二論的原理。」", "st": "complete", "doubt": false}, {"id": "P19-16", "g": "preface", "pdf": 19, "book": null, "hi": "उनके दर्शन का निर्माण करनेवाले रचनात्मक प्रभाव को शायद निगुणात्मक माना जा सकता है।", "rom": "Unakē darśana kā nirmāṇa karanēvālē racanātmaka prabhāva kō śāyada niguṇātmaka mānā jā sakatā hai.", "zh": "構成他哲學的創造性影響，或許可以被看作是無屬性性的。", "st": "complete", "doubt": true}, {"id": "P19-17", "g": "preface", "pdf": 19, "book": null, "hi": "पहले तो संस्कृत और अंग्रेज़ी में उनकी शिक्षा थी।", "rom": "Pahalē tō saṃskṛta aura aṃgrēzī mēṃ unakī śikṣā thī.", "zh": "首先，他受的是梵文與英文教育。", "st": "complete", "doubt": false}, {"id": "P19-18", "g": "preface", "pdf": 19, "book": null, "hi": "इस प्रकार दो जगत् उनके सम्मुख उद्घाटित हुए एवं उनके वैषम्य ने उन पर एक ऐसी विशिष्ट अनुभूति का बलिष्ठ प्रभाव डाला, जो भारत के धर्म-ग्रंथों की विषय-वस्तु है।", "rom": "Isa prakāra dō jagat unakē sammukha udghaṭita huē ēvaṃ unakē vaiṣamya nē una para ēka aisī viśiṣṭa anubhūti kā baliṣṭha prabhāva ḍālā, jō bhārata kē dharma-graṃthōṃ kī viṣaya-vastu hai.", "zh": "這樣一來，兩個世界在他面前展開；它們之間的對比，在他身上產生了一種獨特體驗的強烈影響，而那正是印度宗教典籍的主題。", "st": "complete", "doubt": false}, {"id": "P19-19", "g": "preface", "pdf": 19, "book": null, "hi": "यदि यह सत्य हो, तो यह स्पष्ट है कि वह, जैसे कुछ अन्य लोगों को प्राप्त हो गया, उस प्रकार भारतीय ऋषियों को संयोगवश अप्रत्याशित रूप से नहीं प्राप्त हो गया।", "rom": "Yadi yaha satya hō, tō yaha spaṣṭa hai ki vaha, jaisē kucha anya lōgōṃ kō prāpta hō gayā, usa prakāra bhāratīya ṛṣiyōṃ kō saṃyōgavaśa apratyāśita rūpa sē nahīṃ prāpta hō gayā.", "zh": "如果這是真的，那麼很清楚：它並不是像落到其他一些人身上那樣，偶然地、出乎意料地落到印度先賢身上的。", "st": "complete", "doubt": false}, {"id": "P19-20", "g": "preface", "pdf": 19, "book": null, "hi": "वरन् वह एक विज्ञान की विषय-वस्तु था, एक ऐसे तार्किक विश्लेषण का विषय था, जो सत्य की खोज में बड़े से बड़े बलिदान से पीछे हटनेवाला नहीं था।", "rom": "Varan vaha ēka vijñāna kī viṣaya-vastu thā, ēka aisē tārkika viślēṣaṇa kā viṣaya thā, jō satya kī khōja mēṃ baṛē sē baṛē balidāna sē pīchē haṭanēvālā nahīṃ thā.", "zh": "相反，它是一門科學的主題，是一種邏輯分析的主題；那種分析在尋求真理時，絕不會因再大的犧牲而退縮。", "st": "complete", "doubt": false}, {"id": "P20-01", "g": "preface", "pdf": 20, "book": null, "hi": "अपने गुरु श्री रामकृष्ण परमहंस में, जो दक्षिणेश्वर के उद्यान-मन्दिर में रहते और उपदेश करते थे, स्वामी विवेकानन्द—उन दिनों के ‘नरेन्’—को प्राचीन धर्मग्रंथों का वह सत्यापन प्राप्त हुआ, जिसकी माँग उनका हृदय और बुद्धि करती रही थी।", "rom": "Apanē guru śrī rāmakṛṣṇa paramahaṃsa mēṃ, jō dakṣiṇēśvara kē udyāna-mandira mēṃ rahatē aura upadēśa karatē thē, svāmī vivēkānanda—una dinōṃ kē ‘naren’—kō prācīna dharmagraṃthōṃ kā vaha satyāpana prāpta huā, jisakī māṃga unakā hṛdaya aura buddhi karatī rahī thī.", "zh": "在自己的上師羅摩克里希納大師身上——他住在達克希涅斯瓦爾的花園寺廟裡並在那裡教導——維韋卡南達（那時候的「納倫」）得到了古代典籍的那種驗證，而他的心與理智一直在要求這種驗證。", "st": "complete", "doubt": false}, {"id": "P20-02", "g": "preface", "pdf": 20, "book": null, "hi": "यहाँ वह सत्य उपलब्ध था, जिसका टूटा-फूटा वर्णन ही ग्रंथ कर पाते हैं।", "rom": "Yahāṃ vaha satya upalabdha thā, jisakā ṭūṭā-phūṭā varṇana hī graṃtha kara pātē haiṃ.", "zh": "在這裡可以得到那個真理，而典籍只能對它作支離破碎的描述。", "st": "complete", "doubt": false}, {"id": "P20-03", "g": "preface", "pdf": 20, "book": null, "hi": "यहाँ एक ऐसा व्यक्ति था, जिसके लिए समाधि ही ज्ञान प्राप्त करने का सतत साधन थी।", "rom": "Yahāṃ ēka aisā vyakti thā, jisakē liē samādhi hī jñāna prāpta karanē kā satata sādhana thī.", "zh": "在這裡有這樣一個人，對他而言，三摩地本身就是獲得知識的持續方法。", "st": "complete", "doubt": false}, {"id": "P20-04", "g": "preface", "pdf": 20, "book": null, "hi": "हर घंटे चित्त अनेक से एक की ओर डोलायमान था।", "rom": "Hara ghaṃṭē citta anēka sē ēka kī ōra ḍōlāyamāna thā.", "zh": "每小時，心都在多與一之間擺盪。", "st": "complete", "doubt": false}, {"id": "P20-05", "g": "preface", "pdf": 20, "book": null, "hi": "उनके हर क्षण अतिचेतन भूमिका से संगृहीत ज्ञान की वाणी से ध्वनित होता था।", "rom": "Unakē hara kṣaṇa aticētana bhūmikā sē saṃgṛhīta jñāna kī vāṇī sē dhvanita hōtā thā.", "zh": "他的每一刻，都迴響著從超意識層面所收集的知識之聲。", "st": "complete", "doubt": false}, {"id": "P20-06", "g": "preface", "pdf": 20, "book": null, "hi": "उनके सन्निकट हर व्यक्ति को ईश्वर दर्शन की झलक मिल जाती थी और शिष्य में भी परम ज्ञान की अभीप्सा, ‘ज्वर चढ़ने के सदृश’ जग उठती थी।", "rom": "Unakē sannikaṭa hara vyakti kō īśvara darśana kī jhalaka mila jātī thī aura śiṣya mēṃ bhī parama jñāna kī abhīpsā, ‘jvara caṛhanē kē sadṛśa’ jaga uṭhatī thī.", "zh": "在他身邊的每個人，都能瞥見神的顯現；並且在弟子心中，對至高知識的渴望也像「發燒一樣」被喚醒了。", "st": "complete", "doubt": false}, {"id": "P20-07", "g": "preface", "pdf": 20, "book": null, "hi": "किंतु तथापि वे सम्पूर्ण अज्ञात रूप से ही धर्मग्रंथों की जीवन्त प्रतिमूर्ति थे, क्योंकि उन्होंने उनमें से किसीका कभी अध्ययन ही नहीं किया था !", "rom": "Kiṃtu tathāpi vē sampūrṇa ajñāta rūpa sē hī dharmagraṃthōṃ kī jīvanta pratimūrti thē, kyōṃki unhōṃnē unamēṃ sē kisīkā kabhī adhyayana hī nahīṃ kiyā thā !", "zh": "然而，他完全是在不為人知的情況下，成為典籍活生生的化身，因為他從未真正研讀過其中任何一部！", "st": "complete", "doubt": false}, {"id": "P20-08", "g": "preface", "pdf": 20, "book": null, "hi": "अपने गुरुदेव, रामकृष्ण परमहंस में, विवेकानन्द को जीवन की कुंजी मिल गयी थी।", "rom": "Apanē gurudēva, rāmakṛṣṇa paramahaṃsa mēṃ, vivēkānanda kō jīvana kī kuṃjī mila gayī thī.", "zh": "在自己的上師羅摩克里希納大師身上，維韋卡南達得到了生命的鑰匙。", "st": "complete", "doubt": false}, {"id": "P20-09", "g": "preface", "pdf": 20, "book": null, "hi": "किंतु फिर भी अपने जीवन-कार्य के निमित्त उनकी तैयारी पूरी नहीं हो पायी थी।", "rom": "Kiṃtu phira bhī apanē jīvana-kārya kē nimitta unakī taiyārī pūrī nahīṃ hō pāyī thī.", "zh": "但是，為了自己一生的工作，他的準備仍然沒有完成。", "st": "complete", "doubt": false}, {"id": "P20-10", "g": "preface", "pdf": 20, "book": null, "hi": "उनके गुरुदेव का जीवन एवं व्यक्तित्व, जिस विराट् परिपूर्णता का अल्पकालिक एवं प्रखर प्रतीक था, उसकी परिव्याप्ति को आत्मसात करने के लिए कन्याकुमारी से हिमालय तक, समग्र भारत का भ्रमण करना, सर्वत्र साधु-संत, विद्वानों और जन-साधारण से सम भाव से मिलना, सबसे शिक्षा ग्रहण करना और सबको शिक्षा देना, सबके साथ जीवन बिताना और भारत के अतीत एवं वर्तमान का यथार्थ परिचय प्राप्त करना अनिवार्य था।", "rom": "Unakē gurudēva kā jīvana ēvaṃ vyaktitva, jisa virāṭ paripūrṇatā kā alpakālika ēvaṃ prakhara pratīka thā, usakī parivyāpti kō ātmasāta karanē kē liē kanyākumārī sē himālaya taka, samagra bhārata kā bhramaṇa karanā, sarvatra sādhu-saṃta, vidvānōṃ aura jana-sādhāraṇa sē sama bhāva sē milanā, sabasē śikṣā grahaṇa karanā aura sabakō śikṣā dēnā, sabakē sātha jīvana bitānā aura bhārata kē atīta ēvaṃ vartamāna kā yathārtha paricaya prāpta karanā anivārya thā.", "zh": "為了內化他上師的生命與人格——那是浩大圓滿的短暫而耀眼的象徵——的遍在性，從科摩林角到喜馬拉雅，遍遊整個印度，到處以平等的心與聖者、學者與普通民眾相見，向所有人學習、教導所有人，與所有人一起生活，並獲得對印度過去與現在的真實認識，都是必要的。", "st": "complete", "doubt": false}, {"id": "P20-11", "g": "preface", "pdf": 20, "book": null, "hi": "इस प्रकार विवेकानन्द की कृतियों का संगीत शास्त्र, गुरु तथा मातृभूमि—इन तीन स्वर-लहरियों से निर्मित हुआ है।", "rom": "Isa prakāra vivēkānanda kī kṛtiyōṃ kā saṃgīta śāstra, guru tathā mātṛbhūmi—ina tīna svara-lahariyōṃ sē nirmita huā hai.", "zh": "就這樣，維韋卡南達著作的音樂，是由典籍、上師與祖國這三個音波所構成的。", "st": "complete", "doubt": false}, {"id": "P20-12", "g": "preface", "pdf": 20, "book": null, "hi": "उनके पास देने योग्य यही निधि है।", "rom": "Unakē pāsa dēnē yōgya yahī nidhi hai.", "zh": "他所能給予的寶藏，就是這個。", "st": "complete", "doubt": false}, {"id": "P20-13", "g": "preface", "pdf": 20, "book": null, "hi": "इन्हींसे उनको वे उपकरण मिले, जिनसे विश्व-विकार को दूर करनेवाले आध्यात्मिक वरदान की विशाल्यकरणी उन्होंने प्रस्तुत की।", "rom": "Inhīṃsē unakō vē upakaraṇa milē, jinasē viśva-vikāra kō dūra karanēvālē ādhyātmika varadāna kī viśalyakaraṇī unhōṃnē prastuta kī.", "zh": "正是從這些，他得到了那些工具；憑藉它們，他提出了能消除世界疾患的靈性恩賜的療傷草藥。", "st": "complete", "doubt": false}, {"id": "P20-14", "g": "preface", "pdf": 20, "book": null, "hi": "१९ सितम्बर, १८९३ ई० से ४ जुलाई, १९०२ ई० तक कार्य की अल्पावधि में भारत ने अपनी तथा विश्व की संतति के पथ-प्रदर्शन के लिए उनके हाथों से जो दीप प्रज्वलित एवं प्रतिष्ठित कराया, उसके भीतर ये ही तीन दीपशिखाएँ प्रोज्ज्वल हैं।", "rom": "19 Sitambara, 1893 Ī. sē 4 Julāī, 1902 Ī. taka kārya kī alpāvadhi mēṃ bhārata nē apanī tathā viśva kī saṃtati kē patha-pradarśana kē liē unakē hāthōṃ sē jō dīpa prajvalita ēvaṃ pratiṣṭhita karāyā, usakē bhītara yē hī tīna dīpaśikhāẽ projjvala haiṃ.", "zh": "在1893年9月19日至1902年7月4日這短暫的工作期間，印度為了自己與世界的後代，藉由他的手所點燃並安立的那盞燈中，正是這三個燈焰在閃耀。", "st": "complete", "doubt": false}, {"id": "P20-15", "g": "preface", "pdf": 20, "book": null, "hi": "हममें से कुछ ऐसे लोग भी हैं, जो इसी प्रकार और अपने पीछे छोड़ी गयी उनकी कृतियों के लिए उनको जन्म देनेवाली पुण्यभूमि को, तथा जिन अदृश्य शक्तियों ने उन्हें विश्व में भेजा, उनको धन्य कहते हैं और विश्वास करते हैं कि उनके महान् संदेश की व्यापकता एवं सार्थकता का मर्म जानने में हम अभी तक असमर्थ रहे हैं।", "rom": "Hamamēṃ sē kucha aisē lōga bhī haiṃ, jō isī prakāra aura apanē pīchē chōṛī gayī unakī kṛtiyōṃ kē liē unakō janma dēnēvālī puṇyabhūmi kō, tathā jina adṛśya śaktiyōṃ nē unhēṃ viśva mēṃ bhējā, unakō dhanya kahatē haiṃ aura viśvāsa karatē haiṃ ki unakē mahān saṃdēśa kī vyāpakatā ēvaṃ sārthakatā kā marma jānanē mēṃ hama abhī taka asamartha rahē haiṃ.", "zh": "我們當中也有一些這樣的人：他們同樣地，為了他身後留下的著作，向生養他的聖地，以及把他送到世上來的那些無形力量，稱頌祝福；並且相信，對於他偉大訊息的廣度與意義的奧祕，我們至今仍然無法理解。", "st": "complete", "doubt": false}, {"id": "P21-02", "g": "nivedita", "pdf": 21, "book": null, "hi": "कभी कभी समय की दीर्घ अवधि के बाद एक ऐसा मनुष्य हमारे इस ग्रह में आ पहुँचता है, जो असंदिग्ध रूप से दूसरे किसी मंडल से आया हुआ एक पर्यटक होता है; जो उस अति दूरवर्ती क्षेत्र की, जहाँ से वह आया हुआ है, महिमा, शक्ति और दीप्ति का कुछ अंश इस दुःखपूर्ण संसार में लाता है।", "rom": "Kabhī kabhī samaya kī dīrgha avadhi ke bāda eka aisā manuṣya hamāre isa graha meṃ ā pahuṃcatā hai, jo asaṃdigdha rūpa se dūsare kisī maṇḍala se āyā huā eka paryaṭaka hotā hai; jo usa ati dūravartī kṣetra kī, jahāṃ se vaha āyā huā hai, mahimā, śakti aura dīpti kā kucha aṃśa isa duḥkhapūrṇa saṃsāra meṃ lātā hai.", "zh": "有時候，在漫長的時間之後，一個人會來到我們這個星球，他無疑是從另一個世界來的一位旅人；他把那極遙遠境界的榮耀、力量與光輝的一部分，帶到這個苦難的世界。", "st": "complete", "doubt": false}, {"id": "P21-03", "g": "nivedita", "pdf": 21, "book": null, "hi": "वह मनुष्यों के बीच विचरता है, लेकिन वह इस मर्त्यभूमि का नहीं है।", "rom": "Vaha manuṣyoṃ ke bīca vicaratā hai, lekina vaha isa martyabhūmi kā nahīṃ hai.", "zh": "他在人群中行走，但他不屬於這個塵世。", "st": "complete", "doubt": false}, {"id": "P21-04", "g": "nivedita", "pdf": 21, "book": null, "hi": "वह है एक तीर्थयात्री, एक अजनबी—वह केवल एक रात के लिए ही यहाँ ठहरता है।", "rom": "Vaha hai eka tīrthayātrī, eka ajanabī—vaha kevala eka rāta ke lie hī yahāṃ ṭhaharatā hai.", "zh": "他是一位朝聖者，一位陌生人——他只在這裡停留一夜。", "st": "complete", "doubt": false}, {"id": "P21-05", "g": "nivedita", "pdf": 21, "book": null, "hi": "वह अपने चारों ओर के मनुष्यों के जीवन से अपने को सम्बद्ध पाता है; उनके हर्ष-विषाद का साथी बनता है; उनके साथ सुखी होता है, उनके साथ दुःखी भी होता है; लेकिन इन सबों के बीच, वह यह कभी नहीं भूलता कि वह कौन है, कहाँ से आया है और उसके यहाँ आने का क्या उद्देश्य है।", "rom": "Vaha apane cāroṃ ora ke manuṣyoṃ ke jīvana se apane ko sambaddha pātā hai; unake harṣa-viṣāda kā sāthī banatā hai; unake sātha sukhī hotā hai, unake sātha duḥkhī bhī hotā hai; lekina ina saboṃ ke bīca, vaha yaha kabhī nahīṃ bhūlatā ki vaha kauna hai, kahāṃ se āyā hai aura usake yahāṃ āne kā kyā uddeśya hai.", "zh": "他發現自己與周圍人們的生活相連；成為他們歡樂與悲傷的伴侶；與他們一同快樂，也與他們一同悲傷；但在這一切之中，他從不忘記自己是誰、從何而來，以及來到這裡的目的何在。", "st": "complete", "doubt": false}, {"id": "P21-06", "g": "nivedita", "pdf": 21, "book": null, "hi": "वह कभी अपने दिव्यत्व को नहीं भूलता।", "rom": "Vaha kabhī apane divyatva ko nahīṃ bhūlatā.", "zh": "他從不忘記自己的神性。", "st": "complete", "doubt": false}, {"id": "P21-07", "g": "nivedita", "pdf": 21, "book": null, "hi": "वह सर्वदा याद रखता है कि वह महान्, तेजस्वी एवं महामहिमान्वित आत्मा है।", "rom": "Vaha sarvadā yāda rakhatā hai ki vaha mahān, tejasvī evaṃ mahāmahimānvita ātmā hai.", "zh": "他始終記得，自己是一個偉大、光輝、至為尊崇的靈魂。", "st": "complete", "doubt": false}, {"id": "P21-08", "g": "nivedita", "pdf": 21, "book": null, "hi": "वह जानता है कि वह उस वर्णातीत स्वर्गीय क्षेत्र से आया हुआ है, जहाँ सूर्य अथवा चन्द्र की आवश्यकता नहीं है, क्योंकि वह क्षेत्र आलोकों के आलोक से आलोकित है।", "rom": "Vaha jānatā hai ki vaha usa varṇātīta svargīya kṣetra se āyā huā hai, jahāṃ sūrya athavā candra kī āvaśyakatā nahīṃ hai, kyoṃki vaha kṣetra ālokoṃ ke āloka se ālokita hai.", "zh": "他知道，自己來自那超越言說的天界，在那裡不需要太陽或月亮，因為那境界被光中之光所照亮。", "st": "complete", "doubt": false}, {"id": "P21-09", "g": "nivedita", "pdf": 21, "book": null, "hi": "वह जानता है कि जब ‘ईश्वर की सभी संतानें एक साथ आनन्द के लिए गान कर रही थीं,’ उस समय से बहुत पूर्व ही उसका अस्तित्व था।", "rom": "Vaha jānatā hai ki jaba ‘īśvara kī sabhī santāneṃ eka sātha ānanda ke lie gāna kara rahī thīṃ,’ usa samaya se bahuta pūrva hī usakā astitva thā.", "zh": "他知道，早在「上帝所有的兒女一同歡唱讚美」的時候之前很久，他就已經存在。", "st": "complete", "doubt": false}, {"id": "P21-10", "g": "nivedita", "pdf": 21, "book": null, "hi": "ऐसे एक मनुष्य को मैंने देखा, उसकी वाणी सुनी और उसके प्रति अपनी श्रद्धा अर्पित की।", "rom": "Aise eka manuṣya ko maiṃne dekhā, usakī vāṇī sunī aura usake prati apanī śraddhā arpita kī.", "zh": "這樣的一個人，我見過，聽過他的話語，並向他獻上我的敬意。", "st": "complete", "doubt": false}, {"id": "P21-11", "g": "nivedita", "pdf": 21, "book": null, "hi": "उसीके चरणों में मैंने अपनी आत्मा की अनुरक्ति निवेदित की।", "rom": "Usīke caraṇoṃ meṃ maiṃne apanī ātmā kī anurakti nivedita kī.", "zh": "在他的足下，我獻上了我靈魂的依戀。", "st": "complete", "doubt": false}, {"id": "P21-12", "g": "nivedita", "pdf": 21, "book": null, "hi": "इस प्रकार का मनुष्य सभी तुलना के परे है, क्योंकि वह समस्त साधारण मापदण्डों और आदर्शों के अतीत है।", "rom": "Isa prakāra kā manuṣya sabhī tulanā ke pare hai, kyoṃki vaha samasta sādhāraṇa māpadaṇḍoṃ aura ādarśoṃ ke atīta hai.", "zh": "這樣的人超越一切比較，因為他超越了所有平凡的標準與理想。", "st": "complete", "doubt": false}, {"id": "P21-13", "g": "nivedita", "pdf": 21, "book": null, "hi": "अन्य लोग तेजस्वी हो सकते हैं, लेकिन उसका मन प्रकाशमय है, क्योंकि वह समस्त ज्ञान के स्रोत के साथ अपना संयोग स्थापित करने में समर्थ है।", "rom": "Anya loga tejasvī ho sakate haiṃ, lekina usakā mana prakāśamaya hai, kyoṃki vaha samasta jñāna ke srota ke sātha apanā saṃyoga sthāpita karane meṃ samartha hai.", "zh": "別的人或許光輝，但他的心是光明的，因為他能夠與一切知識的源頭建立連結。", "st": "complete", "doubt": false}, {"id": "P21-14", "g": "nivedita", "pdf": 21, "book": null, "hi": "साधारण मनुष्यों की भाँति वह ज्ञानार्जन की मंथर प्रक्रियाओं द्वारा सीमित नहीं है।", "rom": "Sādhāraṇa manuṣyoṃ kī bhāṃti vaha jñānārjana kī maṃthara prakriyāoṃ dvārā sīmita nahīṃ hai.", "zh": "他不像平凡人那樣，受限於緩慢的求知過程。", "st": "complete", "doubt": false}, {"id": "P21-15", "g": "nivedita", "pdf": 21, "book": null, "hi": "अन्य लोग शायद महान् हो सकते हैं, लेकिन यह महत्त्व उनके अपने वर्ग के दूसरे लोगों की तुलना में ही सम्भव है।", "rom": "Anya loga śāyada mahān ho sakate haiṃ, lekina yaha mahattva unake apane varga ke dūsare logoṃ kī tulanā meṃ hī sambhava hai.", "zh": "別的人或許偉大，但那種偉大只有在與他們自己階層的其他人相比時才成立。", "st": "complete", "doubt": false}, {"id": "P21-16", "g": "nivedita", "pdf": 21, "book": null, "hi": "अन्य मनुष्य अपने साथियों की तुलना में साधु, तेजस्वी, प्रतिभावान हो सकते हैं।", "rom": "Anya manuṣya apane sāthiyoṃ kī tulanā meṃ sādhu, tejasvī, pratibhāvāna ho sakate haiṃ.", "zh": "別的人與同伴相比，或許是善良、光輝、有才華的。", "st": "complete", "doubt": false}, {"id": "P21-17", "g": "nivedita", "pdf": 21, "book": null, "hi": "पर यह सब केवल तुलना की बात है।", "rom": "Para yaha saba kevala tulanā kī bāta hai.", "zh": "但這一切都只是比較的問題。", "st": "complete", "doubt": false}, {"id": "P21-18", "g": "nivedita", "pdf": 21, "book": null, "hi": "एक सन्त साधारण मनुष्य से अधिक पवित्र, अधिक पुण्यवान, अधिक एकनिष्ठ है।", "rom": "Eka santa sādhāraṇa manuṣya se adhika pavitra, adhika puṇyavāna, adhika ekaniṣṭha hai.", "zh": "一位聖者比平凡人更聖潔、更有德行、更專一。", "st": "complete", "doubt": false}, {"id": "P21-19", "g": "nivedita", "pdf": "21-22", "book": null, "hi": "किंतु स्वामी विवेकानन्द के सम्बन्ध में कोई तुलना नहीं हो सकती।", "rom": "Kiṃtu svāmī vivekānanda ke sambandha meṃ koī tulanā nahīṃ ho sakatī.", "zh": "但就維韋卡南達而言，沒有任何比較可言。", "st": "complete", "doubt": false}, {"id": "P22-01", "g": "nivedita", "pdf": 22, "book": null, "hi": "वे स्वयं ही अपने वर्ग के हैं।", "rom": "Ve svayaṃ hī apane varga ke haiṃ.", "zh": "他自成一類。", "st": "complete", "doubt": false}, {"id": "P22-02", "g": "nivedita", "pdf": 22, "book": null, "hi": "वे एक दूसरे स्तर के हैं, न कि इस सांसारिक स्तर के।", "rom": "Ve eka dūsare stara ke haiṃ, na ki isa sāṃsārika stara ke.", "zh": "他屬於另一個層次，而不是這個世俗的層次。", "st": "complete", "doubt": false}, {"id": "P22-03", "g": "nivedita", "pdf": 22, "book": null, "hi": "वे एक भास्वर सत्ता हैं, जो एक सुनिर्दिष्ट प्रयोजन के लिए दूसरे एक उच्चतर मंडल से इस मर्त्यभूमि पर अवतरित हुए हैं।", "rom": "Ve eka bhāsvara sattā haiṃ, jo eka sunirdiṣṭa prayojana ke lie dūsare eka uccatara maṇḍala se isa martyabhūmi para avatarita hue haiṃ.", "zh": "他是一個光輝的存在，為了一個明確的目的，從另一個更高的世界降臨到這個塵世。", "st": "complete", "doubt": false}, {"id": "P22-04", "g": "nivedita", "pdf": 22, "book": null, "hi": "कोई शायद जान सकता था कि वे यहाँ पर दीर्घ काल तक नहीं ठहरेंगे।", "rom": "Koī śāyada jāna sakatā thā ki ve yahāṃ para dīrgha kāla taka nahīṃ ṭhahareṃge.", "zh": "也許有人早已知道，他不會在這裡久留。", "st": "complete", "doubt": false}, {"id": "P22-05", "g": "nivedita", "pdf": 22, "book": null, "hi": "इसमें क्या आश्चर्य है कि प्रकृति स्वयं ऐसे मनुष्य के जन्म पर आनन्द मनाती है, स्वर्ग के द्वार खुल जाते हैं और देवदूत कीर्ति-गान करते हैं?", "rom": "Isameṃ kyā āścarya hai ki prakṛti svayaṃ aise manuṣya ke janma para ānanda manātī hai, svarga ke dvāra khula jāte haiṃ aura devadūta kīrti-gāna karate haiṃ?", "zh": "大自然本身為這樣一個人的誕生而歡欣、天門開啟、天使歌頌榮耀，這有什麼可奇怪的呢？", "st": "complete", "doubt": false}, {"id": "P22-06", "g": "nivedita", "pdf": 22, "book": null, "hi": "धन्य है वह देश, जिसने उनको जन्म दिया है; धन्य हैं वे मनुष्य, जो उस समय इस पृथ्वी पर जीवित थे; और धन्य हैं वे कुछ लोग—धन्य, धन्य, धन्य—जिन्हें उनके पादपद्मों में बैठने का सौभाग्य मिला था।", "rom": "Dhanya hai vaha deśa, jisane unako janma diyā hai; dhanya haiṃ ve manuṣya, jo usa samaya isa pṛthvī para jīvita the; aura dhanya haiṃ ve kucha loga—dhanya, dhanya, dhanya—jinheṃ unake pādapadmoṃ meṃ baiṭhane kā saubhāgya milā thā.", "zh": "有福的是那生養他的國土；有福的是那些在他那個時代活在世上的人；有福的是那些少數人——有福、有福、有福——他們有幸坐在他的蓮足旁。", "st": "complete", "doubt": false}, {"id": "WEL-01", "g": "welcome", "pdf": 25, "book": 3, "hi": "अमेरिकावासी बहनो तथा भाइयो,", "rom": "Amerikāvāsī bahano tathā bhāiyo,", "zh": "美國的姊妹們、兄弟們，", "st": "complete", "doubt": false}, {"id": "WEL-02", "g": "welcome", "pdf": 25, "book": 3, "hi": "आपने जिस सौहार्द और स्नेह के साथ हम लोगों का स्वागत किया है, उसके प्रति आभार प्रकट करने के निमित्त खड़े होते समय मेरा हृदय अवर्णनीय हर्ष से पूर्ण हो रहा है।", "rom": "Āpane jis sauhārda aura sneha ke sātha ham logoṁ kā svāgata kiyā hai, usake prati ābhāra prakaṭa karane ke nimitta khaṛe hote samaya merā hṛdaya avarṇanīya harṣa se pūrṇa ho rahā hai.", "zh": "此刻站起來，為了向你們以如此親切與深情歡迎我們表達感謝，我的心中充滿了難以言喻的喜悅。", "st": "complete", "doubt": false}, {"id": "WEL-03", "g": "welcome", "pdf": 25, "book": 3, "hi": "संसार में संन्यासियों की सबसे प्राचीन परम्परा की ओर से मैं आपको धन्यवाद देता हूँ; धर्मों की माता की ओर से धन्यवाद देता हूँ; और सभी सम्प्रदायों एवं मतों के कोटि कोटि हिन्दुओं की ओर से भी धन्यवाद देता हूँ।", "rom": "Saṁsāra meṁ saṁnyāsiyoṁ kī sabase prācīna paramparā kī ora se maiṁ āpako dhanyavāda detā hūṁ; dharmoṁ kī mātā kī ora se dhanyavāda detā hūṁ; aura sabhī sampradāyoṁ evaṁ matoṁ ke koṭi koṭi hinduoṁ kī ora se bhī dhanyavāda detā hūṁ.", "zh": "我代表世界上最古老的出家修行者傳統向你們致謝；代表眾宗教之母向你們致謝；也代表千千萬萬印度教徒、各宗派、各信仰向你們致謝。", "st": "complete", "doubt": false}, {"id": "WEL-04", "g": "welcome", "pdf": 25, "book": 3, "hi": "मैं इस मंच पर से बोलनेवाले उन कतिपय वक्ताओं के प्रति भी धन्यवाद ज्ञापित करता हूँ, जिन्होंने प्राची के प्रतिनिधियों का उल्लेख करते समय आपको यह बतलाया है कि सुदूर देशों के ये लोग सहिष्णुता का भाव विविध देशों में प्रसारित करने के गौरव का दावा कर सकते हैं।", "rom": "Maiṁ isa maṁca para se bolanevāle una katipaya vaktāoṁ ke prati bhī dhanyavāda jñāpita kartā hūṁ, jinhoṁne prācī ke pratinidhiyoṁ kā ullekha karate samaya āpako yaha batalāyā hai ki sudūra deśoṁ ke ye loga sahiṣṇutā kā bhāva vividha deśoṁ meṁ prasārita karane ke gaurava kā dāvā kara sakate haiṁ.", "zh": "我也要向在這個講台上發言的幾位演講者致謝，他們在提到東方代表時告訴你們：來自遙遠國度的這些人，可以自豪地宣稱自己把寬容的精神傳播到各國。", "st": "complete", "doubt": false}, {"id": "WEL-05", "g": "welcome", "pdf": 25, "book": 3, "hi": "मैं एक ऐसे धर्म का अनुयायी होने में गर्व का अनुभव करता हूँ, जिसने संसार को सहिष्णुता तथा सार्वभौम स्वीकृति, दोनों की ही शिक्षा दी है।", "rom": "Maiṁ eka aise dharma kā anuyāyī hone meṁ garva kā anubhava kartā hūṁ, jisane saṁsāra ko sahiṣṇutā tathā sārvabhauma svīkṛti, donoṁ kī hī śikṣā dī hai.", "zh": "我為自己是這樣一種宗教的追隨者而感到自豪，它教導世人寬容與普遍接納，兩者兼備。", "st": "complete", "doubt": false}, {"id": "WEL-06", "g": "welcome", "pdf": 25, "book": 3, "hi": "हम लोग सब धर्मों के प्रति केवल सहिष्णुता में ही विश्वास नहीं करते, वरन् समस्त धर्मों को सच्चा मानकर स्वीकार करते हैं।", "rom": "Ham loga saba dharmoṁ ke prati kevala sahiṣṇutā meṁ hī viśvāsa nahīṁ karate, varan samasta dharmoṁ ko saccā mānakara svīkāra karate haiṁ.", "zh": "我們對所有宗教不僅僅是相信寬容，更是把一切宗教都視為真實而加以接受。", "st": "complete", "doubt": true}, {"id": "WEL-07", "g": "welcome", "pdf": 25, "book": 3, "hi": "मुझे एक ऐसे देश का व्यक्ति होने का अभिमान है, जिसने इस पृथ्वी के समस्त धर्मों और देशों के उत्पीड़ितों और शरणार्थियों को आश्रय दिया है।", "rom": "Mujhe eka aise deśa kā vyakti hone kā abhimāna hai, jisane isa pṛthvī ke samasta dharmoṁ aura deśoṁ ke utpīṛitoṁ aura śaraṇārthiyoṁ ko āśraya diyā hai.", "zh": "我為自己是這樣一個國家的人而感到驕傲，這個國家庇護了這世上所有宗教與國家的受迫害者與難民。", "st": "complete", "doubt": false}, {"id": "WEL-08", "g": "welcome", "pdf": 25, "book": 3, "hi": "मुझे आपको यह बतलाते हुए गर्व होता है कि हमने अपने वक्ष में यहूदियों के विशुद्धतम अवशिष्ट अंश को स्थान दिया था, जिन्होंने दक्षिण भारत आकर उसी वर्ष शरण ली थी, जिस वर्ष उनका पवित्र मंदिर रोमन जाति के अत्याचार से धूल में मिला दिया गया था।", "rom": "Mujhe āpako yaha batalāte hue garva hotā hai ki hamane apane vakṣa meṁ yahūdiyoṁ ke viśuddhatama avaśiṣṭa aṁśa ko sthāna diyā thā, jinhoṁne dakṣiṇa bhārata ākara usī varṣa śaraṇa lī thī, jisa varṣa unakā pavitra maṁdira romana jāti ke atyācāra se dhūla meṁ milā diyā gayā thā.", "zh": "我很自豪地告訴你們：我們曾把猶太人最純淨的殘存部分迎入懷中，他們來到南印度、於同一年尋求庇護，而就在那一年，他們的神聖聖殿被羅馬人的暴行夷為塵土。", "st": "complete", "doubt": false}, {"id": "WEL-09", "g": "welcome", "pdf": 25, "book": 3, "hi": "ऐसे धर्म का अनुयायी होने में मैं गर्व का अनुभव करता हूँ, जिसने महान् जरथुष्ट्र जाति के अवशिष्ट अंश को शरण दी और जिसका पालन वह अब तक कर रहा है।", "rom": "Aise dharma kā anuyāyī hone meṁ maiṁ garva kā anubhava kartā hūṁ, jisane mahān jarathuṣṭra jāti ke avaśiṣṭa aṁśa ko śaraṇa dī aura jisakā pālana vaha aba taka kara rahā hai.", "zh": "我為自己是這樣一種宗教的追隨者而感到自豪，它庇護了偉大的瑣羅亞斯德教民族的殘存部分，並且至今仍在護持他們。", "st": "complete", "doubt": false}, {"id": "WEL-10", "g": "welcome", "pdf": 25, "book": 3, "hi": "भाइयो, मैं आप लोगों को एक स्तोत्र की कुछ पंक्तियाँ सुनाता हूँ, जिसकी आवृत्ति मैं अपने बचपन से करता रहा हूँ और जिसकी आवृत्ति प्रतिदिन लाखों मनुष्य किया करते हैं:", "rom": "Bhāiyo, maiṁ āpa logoṁ ko eka stotra kī kucha paṁktiyāṁ sunātā hūṁ, jisakī āvṛtti maiṁ apane bacapana se karatā rahā hūṁ aura jisakī āvṛtti pratidina lākhoṁ manuṣya kiyā karate haiṁ:", "zh": "兄弟們，我要為你們誦念一首讚頌詩的幾行，我從童年起就反覆誦念它，每天也有千千萬萬人反覆誦念它：", "st": "complete", "doubt": false}, {"id": "WEL-11", "g": "welcome", "pdf": 26, "book": 4, "hi": "—‘जैसे विभिन्न नदियाँ भिन्न भिन्न स्रोतों से निकलकर समुद्र में मिल जाती हैं, उसी प्रकार हे प्रभो ! भिन्न भिन्न रुचि के अनुसार विभिन्न टेढ़े-मेढ़े अथवा सीधे रास्ते से जानेवाले लोग अन्त में तुझमें ही आकर मिल जाते हैं।’", "rom": "—‘Jaise vibhinna nadiyāṁ bhinna bhinna srotoṁ se nikalakara samudra meṁ mila jātī haiṁ, usī prakāra he prabho! Bhinna bhinna ruci ke anusāra vibhinna ṭeṛhe-meṛhe athavā sīdhe rāste se jānevāle loga anta meṁ tujhameṁ hī ākara mila jāte haiṁ.’", "zh": "——『正如不同的河流從不同的源頭流出而匯入海洋，同樣地，主啊！依各自不同的喜好，走曲折或筆直道路的人們，最終都歸向你。』", "st": "complete", "doubt": false}, {"id": "WEL-12", "g": "welcome", "pdf": 26, "book": 4, "hi": "यह सभा, जो अभी तक आयोजित सर्वश्रेष्ठ पवित्र सम्मेलनों में से एक है, स्वतः ही गीता के इस अद्भुत उपदेश का प्रतिपादन एवं जगत् के प्रति उसकी घोषणा है:", "rom": "Yaha sabhā, jo abhī taka āyojita sarvaśreṣṭha pavitra sammelanoṁ meṁ se eka hai, svataḥ hī gītā ke isa adbhuta upadeśa kā pratipādana evaṁ jagat ke prati usakī ghoṣaṇā hai:", "zh": "這個大會，作為迄今所舉辦的最崇高的神聖集會之一，本身就是《薄伽梵歌》這段奇妙教誨的闡述與向世界的宣告：", "st": "complete", "doubt": false}, {"id": "WEL-13", "g": "welcome", "pdf": 26, "book": 4, "hi": "—‘जो कोई मेरी ओर आता है—चाहे किसी प्रकार से हो—मैं उसको प्राप्त होता हूँ।", "rom": "—‘Jo koī merī ora ātā hai—cāhe kisī prakāra se ho—maiṁ usako prāpta hotā hūṁ.", "zh": "——『無論誰走向我——無論以何種方式——我都會接納他。", "st": "complete", "doubt": false}, {"id": "WEL-14", "g": "welcome", "pdf": 26, "book": 4, "hi": "लोग भिन्न भिन्न मार्ग द्वारा प्रयत्न करते हुए अंत में मेरी ही ओर आते हैं।’", "rom": "Loga bhinna bhinna mārga dvārā prayatna karate hue anta meṁ merī hī ora āte haiṁ.’", "zh": "人們經由不同的道路努力前行，最終都走向我。』", "st": "complete", "doubt": false}, {"id": "WEL-15", "g": "welcome", "pdf": 26, "book": 4, "hi": "साम्प्रदायिकता, हठधर्मिता और उनकी वीभत्स वंशधर धर्मान्धता इस सुन्दर पृथ्वी पर बहुत समय तक राज्य कर चुकी हैं।", "rom": "Sāmpradāyikatā, haṭhadharmitā aura unakī vībhatsa vaṁśadhara dharmāndhatā isa sundara pṛthvī para bahuta samaya taka rājya kara cukī haiṁ.", "zh": "宗派主義、頑固教條，以及它們那可怕的後代——宗教狂熱，已經在這美麗的地球上統治了很久。", "st": "complete", "doubt": false}, {"id": "WEL-16", "g": "welcome", "pdf": 26, "book": 4, "hi": "वे पृथ्वी को हिंसा से भरती रही हैं, उसको बारम्बार मानवता के रक्त से नहलाती रही हैं, सभ्यताओं को विध्वस्त करती और पूरे पूरे देशों को निराशा के गर्त में डालती रही हैं।", "rom": "Ve pṛthvī ko hiṁsā se bharatī rahī haiṁ, usako bārambāra mānavatā ke rakta se nahalātī rahī haiṁ, sabhyatāoṁ ko vidhvasta karatī aura pūre pūre deśoṁ ko nirāśā ke garta meṁ ḍālatī rahī haiṁ.", "zh": "它們不斷以暴力充滿大地，一再以人類的鮮血浸染大地，摧毀文明，把整個整個國家推入絕望的深淵。", "st": "complete", "doubt": false}, {"id": "WEL-17", "g": "welcome", "pdf": 26, "book": 4, "hi": "यदि ये वीभत्स दानवी न होतीं, तो मानव-समाज आज की अवस्था से कहीं अधिक उन्नत हो गया होता।", "rom": "Yadi ye vībhatsa dānavī na hotīṁ, to mānava-samāja āja kī avasthā se kahīṁ adhika unnata ho gayā hotā.", "zh": "如果沒有這些可怕的女妖，人類社會今天會比現在進步得多。", "st": "complete", "doubt": false}, {"id": "WEL-18", "g": "welcome", "pdf": 26, "book": 4, "hi": "पर अब उनका समय आ गया है, और मैं आंतरिक रूप से आशा करता हूँ कि आज सुबह इस सभा के सम्मान में जो घंटा-ध्वनि हुई है, वह समस्त धर्मान्धता का, तलवार या लेखनी के द्वारा होनेवाले सभी उत्पीड़नों का, तथा एक ही लक्ष्य की ओर अग्रसर होनेवाले मानवों की पारस्परिक कटुताओं का मृत्यु-निनाद सिद्ध हो।", "rom": "Para aba unakā samaya ā gayā hai, aura maiṁ āṁtarika rūpa se āśā kartā hūṁ ki āja subaha isa sabhā ke sammāna meṁ jo ghaṇṭā-dhvani huī hai, vaha samasta dharmāndhatā kā, talavāra yā lekhanī ke dvārā honevāle sabhī utpīṛaṇoṁ kā, tathā eka hī lakṣya kī ora agrasara honevāle mānavoṁ kī pārasparika kaṭutāoṁ kā mṛtyu-nināda siddha ho.", "zh": "但現在，它們的時日已經到了，我由衷希望：今天早上為尊敬這個大會而響起的鐘聲，能成為一切宗教狂熱、一切以刀劍或筆桿進行的迫害，以及朝向同一目標前進的人們之間彼此苦毒的喪鐘。", "st": "complete", "doubt": false}, {"id": "FROG-01", "g": "frog", "pdf": 27, "book": 5, "hi": "मैं आप लोगों को एक छोटी सी कहानी सुनाता हूँ।", "rom": "Maiṁ āpa logoṁ ko eka choṭī sī kahānī sunātā hūṁ.", "zh": "我要給你們講一個小故事。", "st": "complete", "doubt": false}, {"id": "FROG-02", "g": "frog", "pdf": 27, "book": 5, "hi": "अभी जिन वाग्मी वक्ता महोदय ने व्याख्यान समाप्त किया है, उनके इस वचन को आप लोगों ने सुना है कि ‘आओ, हम लोग एक दूसरे को बुरा कहना बंद कर दें’, और उन्हें इस बात का बड़ा खेद है कि लोगों में सदा इतना मतभेद क्यों रहता है।", "rom": "Abhī jina vāgmī vaktā mahodaya ne vyākhyāna samāpta kiyā hai, unake isa vacana ko āpa logoṁ ne sunā hai ki ‘Āo, ham loga eka dūsare ko burā kahanā baṁda kara deṁ’, aura unheṁ isa bāta kā baṛā kheda hai ki logoṁ meṁ sadā itanā matabheda kyoṁ rahatā hai.", "zh": "剛才那位雄辯的演講先生結束演講時，你們都聽到了他的話：『來吧，讓我們停止彼此說壞話』，而且他很遺憾人們之間總是存在這麼多分歧。", "st": "complete", "doubt": false}, {"id": "FROG-03", "g": "frog", "pdf": 27, "book": 5, "hi": "परन्तु मैं समझता हूँ कि जो कहानी मैं सुनानेवाला हूँ, उससे आप लोगों को इस मतभेद का कारण स्पष्ट हो जायगा।", "rom": "Parantu maiṁ samajhatā hūṁ ki jo kahānī maiṁ sunānevālā hūṁ, usase āpa logoṁ ko isa matabheda kā kāraṇa spaṣṭa ho jāyagā.", "zh": "但我認為，我要講的這個故事，會讓你們明白這種分歧的原因。", "st": "complete", "doubt": false}, {"id": "FROG-04", "g": "frog", "pdf": 27, "book": 5, "hi": "एक कुएँ में बहुत समय से एक मेढक रहता था।", "rom": "Eka kuẽ meṁ bahuta samaya se eka meṛhaka rahatā thā.", "zh": "很久以前，一口井裡住著一隻青蛙。", "st": "complete", "doubt": false}, {"id": "FROG-05", "g": "frog", "pdf": 27, "book": 5, "hi": "वह वहीं पैदा हुआ था और वहीं उसका पालन-पोषण हुआ, पर फिर भी वह मेढक छोटा ही था।", "rom": "Vaha vahīṁ paidā huā thā aura vahīṁ usakā pālana-poṣaṇa huā, para phira bhī vaha meṛhaka choṭā hī thā.", "zh": "牠就出生在那裡，也在那裡長大，但即便如此，牠仍然很小。", "st": "complete", "doubt": false}, {"id": "FROG-06", "g": "frog", "pdf": 27, "book": 5, "hi": "हाँ, आज के क्रमविकासवादी (evolutionists) उस समय वहाँ नहीं थे, जो हमें यह बतला सकते कि उस मेढक की आँखें थीं अथवा नहीं, पर यहाँ कहानी के लिए यह मान लेना चाहिए कि उसकी आँखें थीं, और वह प्रतिदिन ऐसे पुरुषार्थ के साथ जल को सारे कीड़ों और कीटाणुओं से रहित पूर्ण स्वच्छ कर देता था कि उतना पुरुषार्थ हमारे आधुनिक कीटाणुवादियों (bacteriologists) को यशस्वी बना दें।", "rom": "Hāṁ, āja ke kramavikāsavādī (evolutionists) usa samaya vahāṁ nahīṁ the, jo hameṁ yaha batalā sakate ki usa meṛhaka kī āṁkheṁ thīṁ athavā nahīṁ, para yahāṁ kahānī ke lie yaha māna lenā cāhie ki usakī āṁkheṁ thīṁ, aura vaha pratidina aise puruṣārtha ke sātha jala ko sāre kīṛoṁ aura kīṭāṇuoṁ se rahita pūrṇa svaccha kara detā thā ki utanā puruṣārtha hamāre ādhunika kīṭāṇuvādiyoṁ (bacteriologists) ko yaśasvī banā deṁ.", "zh": "是的，今天的進化論者那時還不在場，無法告訴我們那隻青蛙到底有沒有眼睛；但就這個故事而言，我們得假定牠有眼睛，而且牠每天都那麼努力地把水裡所有的蟲子和細菌清除得乾乾淨淨，那份努力足以讓我們現代的細菌學家功成名就。", "st": "complete", "doubt": false}, {"id": "FROG-07", "g": "frog", "pdf": 27, "book": 5, "hi": "इस प्रकार धीरे धीरे यह मेढक उसी कुएँ में रहते रहते मोटा और चिकना हो गया।", "rom": "Isa prakāra dhīre dhīre yaha meṛhaka usī kuẽ meṁ rahate rahate moṭā aura cikanā ho gayā.", "zh": "就這樣，這隻青蛙在同一口井裡慢慢長得又肥又光滑。", "st": "complete", "doubt": false}, {"id": "FROG-08", "g": "frog", "pdf": 27, "book": 5, "hi": "अब एक दिन एक दूसरा मेढक, जो समुद्र में रहता था, वहाँ आया और कुएँ में गिर पड़ा।", "rom": "Aba eka dina eka dūsarā meṛhaka, jo samudra meṁ rahatā thā, vahāṁ āyā aura kuẽ meṁ gira paṛā.", "zh": "有一天，另一隻住在海裡的青蛙來到這裡，掉進了井裡。", "st": "complete", "doubt": false}, {"id": "FROG-09", "g": "frog", "pdf": 27, "book": 5, "hi": "“तुम कहाँ से आये हो ?”", "rom": "“Tuma kahāṁ se āye ho?”", "zh": "「你是從哪裡來的？」", "st": "complete", "doubt": false}, {"id": "FROG-10", "g": "frog", "pdf": 27, "book": 5, "hi": "“मैं समुद्र से आया हूँ।”", "rom": "“Maiṁ samudra se āyā hūṁ.”", "zh": "「我是從海裡來的。」", "st": "complete", "doubt": false}, {"id": "FROG-11", "g": "frog", "pdf": 27, "book": 5, "hi": "“समुद्र !”", "rom": "“Samudra!”", "zh": "「海！」", "st": "complete", "doubt": false}, {"id": "FROG-12", "g": "frog", "pdf": 27, "book": 5, "hi": "भला, कितना बड़ा है वह ?", "rom": "Bhalā, kitanā baṛā hai vaha?", "zh": "好吧，它到底有多大？", "st": "complete", "doubt": false}, {"id": "FROG-13", "g": "frog", "pdf": 27, "book": 5, "hi": "क्या वह भी इतना ही बड़ा है, जितना मेरा यह कुआँ ?”", "rom": "Kyā vaha bhī itanā hī baṛā hai, jitanā merā yaha kuāṁ?”", "zh": "它也像我的這口井一樣大嗎？」", "st": "complete", "doubt": false}, {"id": "FROG-14", "g": "frog", "pdf": 28, "book": 6, "hi": "और यह कहते हुए उसने कुएँ में एक किनारे से दूसरे किनारे तक छलाँग मारी।", "rom": "Aura yaha kahate hue usane kuẽ meṁ eka kināre se dūsare kināre taka chalāṁga mārī.", "zh": "說著，牠在井裡從一邊跳到了另一邊。", "st": "complete", "doubt": false}, {"id": "FROG-15", "g": "frog", "pdf": 28, "book": 6, "hi": "समुद्रवाले मेढक ने कहा, “मेरे मित्र !”", "rom": "Samudravāle meṛhaka ne kahā, “Mere mitra!”", "zh": "海裡來的青蛙說：「我的朋友！」", "st": "complete", "doubt": false}, {"id": "FROG-16", "g": "frog", "pdf": 28, "book": 6, "hi": "भला, समुद्र की तुलना इस छोटे से कुएँ से किस प्रकार कर सकते हो ?”", "rom": "Bhalā, samudra kī tulanā isa choṭe se kuẽ se kisa prakāra kara sakate ho?”", "zh": "好吧，你怎麼能把大海和這口小井相提並論呢？」", "st": "complete", "doubt": false}, {"id": "FROG-17", "g": "frog", "pdf": 28, "book": 6, "hi": "तब उस कुएँवाले मेढक ने एक दूसरी छलाँग मारी और पूछा, “तो क्या तुम्हारा समुद्र इतना बड़ा है ?”", "rom": "Taba usa kuẽvāle meṛhaka ne eka dūsarī chalāṁga mārī aura pūchā, “To kyā tumhārā samudra itanā baṛā hai?”", "zh": "於是井裡的青蛙又跳了一下，問道：「那麼，你的海有這麼大嗎？」", "st": "complete", "doubt": false}, {"id": "FROG-18", "g": "frog", "pdf": 28, "book": 6, "hi": "समुद्रवाले मेढक ने कहा, “तुम कैसी बेवकूफ़ी की बात कर रहे हो !”", "rom": "Samudravāle meṛhaka ne kahā, “Tuma kaisī bevakūfī kī bāta kara rahe ho!”", "zh": "海裡來的青蛙說：「你在說什麼蠢話！」", "st": "complete", "doubt": false}, {"id": "FROG-19", "g": "frog", "pdf": 28, "book": 6, "hi": "क्या समुद्र की तुलना तुम्हारे कुएँ से हो सकती है ?”", "rom": "Kyā samudra kī tulanā tumhāre kuẽ se ho sakatī hai?”", "zh": "大海怎麼能和你的井相比呢？」", "st": "complete", "doubt": false}, {"id": "FROG-20", "g": "frog", "pdf": 28, "book": 6, "hi": "अब तो कुएँवाले मेढक ने कहा, “जा, जा !”", "rom": "Aba to kuẽvāle meṛhaka ne kahā, “Jā, jā!”", "zh": "這時井裡的青蛙說：「走開，走開！」", "st": "complete", "doubt": false}, {"id": "FROG-21", "g": "frog", "pdf": 28, "book": 6, "hi": "मेरे कुएँ से बढ़कर और कुछ हो ही नहीं सकता।", "rom": "Mere kuẽ se baṛhakara aura kucha ho hī nahīṁ sakatā.", "zh": "沒有什麼能比我的井更大。", "st": "complete", "doubt": false}, {"id": "FROG-22", "g": "frog", "pdf": 28, "book": 6, "hi": "संसार में इससे बड़ा और कुछ नहीं है !", "rom": "Saṁsāra meṁ isase baṛā aura kucha nahīṁ hai!", "zh": "世界上沒有比這更大的東西了！", "st": "complete", "doubt": false}, {"id": "FROG-23", "g": "frog", "pdf": 28, "book": 6, "hi": "झूठा कहीं का !", "rom": "Jhūṭhā kahīṁ kā!", "zh": "真是個騙子！", "st": "complete", "doubt": false}, {"id": "FROG-24", "g": "frog", "pdf": 28, "book": 6, "hi": "अरे, इसे बाहर निकाल दो !”", "rom": "Are, ise bāhara nikāla do!”", "zh": "哎呀，把牠趕出去！」", "st": "complete", "doubt": false}, {"id": "FROG-25", "g": "frog", "pdf": 28, "book": 6, "hi": "यही कठिनाई सदैव रही है।", "rom": "Yahī kaṭhināī sadaiva rahī hai.", "zh": "困難一直就在這裡。", "st": "complete", "doubt": false}, {"id": "FROG-26", "g": "frog", "pdf": 28, "book": 6, "hi": "मैं हिन्दू हूँ।", "rom": "Maiṁ hindū hūṁ.", "zh": "我是印度教徒。", "st": "complete", "doubt": false}, {"id": "FROG-27", "g": "frog", "pdf": 28, "book": 6, "hi": "मैं अपने क्षुद्र कुएँ में बैठा यही समझता हूँ कि मेरा कुआँ ही संपूर्ण संसार है।", "rom": "Maiṁ apane kṣudra kuẽ meṁ baiṭhā yahī samajhatā hūṁ ki merā kuāṁ hī saṁpūrṇa saṁsāra hai.", "zh": "我坐在自己狹小的井裡，總以為我的井就是整個世界。", "st": "complete", "doubt": false}, {"id": "FROG-28", "g": "frog", "pdf": 28, "book": 6, "hi": "ईसाई भी अपने क्षुद्र कुएँ में बैठे हुए यही समझता है कि सारा संसार उसीके कुएँ में है और मुसलमान भी अपने क्षुद्र कुएँ में बैठा हुआ उसीको सारा ब्रह्माण्ड मानता है।", "rom": "Īsāī bhī apane kṣudra kuẽ meṁ baiṭhe hue yahī samajhatā hai ki sārā saṁsāra usīke kuẽ meṁ hai aura musalamāna bhī apane kṣudra kuẽ meṁ baiṭhā huā usīko sārā brahmāṇḍa mānatā hai.", "zh": "基督徒也坐在自己狹小的井裡，以為整個世界都在他的井裡；穆斯林也坐在自己狹小的井裡，把那口井當作整個宇宙。", "st": "complete", "doubt": false}, {"id": "FROG-29", "g": "frog", "pdf": 28, "book": 6, "hi": "मैं आप अमेरिकावालों को धन्य कहता हूँ, क्योंकि आप हम लोगों के इन छोटे छोटे संसारों की क्षुद्र सीमाओं को तोड़ने का महान् प्रयत्न कर रहे हैं, और मैं आशा करता हूँ कि भविष्य में परमात्मा आपके इस उद्योग में सहायता देकर आपका मनोरथ पूर्ण करेंगे।", "rom": "Maiṁ āpa amerikāvāloṁ ko dhanya kahatā hūṁ, kyoṁki āpa ham logoṁ ke ina choṭe choṭe saṁsāroṁ kī kṣudra sīmāoṁ ko toṛane kā mahān prayatna kara rahe haiṁ, aura maiṁ āśā kartā hūṁ ki bhaviṣya meṁ paramātmā āpake isa udyoga meṁ sahāyatā dekara āpakā manoratha pūrṇa kareṁge.", "zh": "我要向你們美國人致謝，因為你們正在努力打破我們這些小小世界的狹隘界限；我也希望，將來上帝會在你們的這項事業上幫助你們，成全你們的心願。", "st": "complete", "doubt": false}, {"id": "HINDU-01", "g": "hindu", "pdf": 29, "book": 7, "hi": "प्रागैतिहासिक युग से चले आनेवाले केवल तीन ही धर्म आज संसार में विद्यमान हैं—हिन्दू धर्म, पारसी धर्म और यहूदी धर्म।", "rom": "Prāgaitihāsika yuga se cale ānevāle kevala tīna hī dharma āja saṁsāra meṁ vidyamāna haiṁ—Hindū dharma, Pārasī dharma aura Yahūdī dharma.", "zh": "從史前時代延續至今的宗教，現今世界上只有三種——印度教、祆教和猶太教。", "st": "complete", "doubt": false}, {"id": "HINDU-02", "g": "hindu", "pdf": 29, "book": 7, "hi": "उनको अनेकानेक प्रचंड आघात सहने पड़े हैं, किन्तु फिर भी जीवित बने रहकर वे सभी अपनी आन्तरिक शक्ति का प्रमाण प्रस्तुत करते हैं।", "rom": "Unako anekāneka pracaṇḍa āghāta sahane paṛe haiṁ, kintu phira bhī jīvita bane rahakara ve sabhī apanī āntarika śakti kā pramāṇa prastuta karate haiṁ.", "zh": "它們遭受了無數猛烈的打擊，但仍然存活下來，都以此證明了自己內在的力量。", "st": "complete", "doubt": false}, {"id": "HINDU-03", "g": "hindu", "pdf": 29, "book": 7, "hi": "पर जहाँ हम यह देखते हैं कि यहूदी धर्म ईसाई धर्म को आत्मसात नहीं कर सका, वरन् अपनी सर्वविजयिनी दुहिता—ईसाई धर्म—द्वारा अपने जन्म-स्थान से निर्वासित कर दिया गया, और केवल मुट्ठी भर पारसी ही अपने महान् धर्म की गाथा गाने के लिए अब अवशेष हैं,—वहाँ भारत में एक के बाद एक न जाने कितने सम्प्रदायों का उदय हुआ और उन्होंने वैदिक धर्म को जड़ से हिला सा दिया; किन्तु भयंकर भूकम्प के समय समुद्र-तट के जल के समान वह कुछ समय पश्चात् हज़ार गुना बलशाली होकर सर्वग्रासी आप्लावन के रूप में पुनः लौटने के लिए पीछे हट गया; और जब यह सारा कोलाहल शान्त हो गया, तब इन समस्त धर्म-सम्प्रदायों को उनकी धर्म-माता (हिंदू धर्म) की विराट् काया ने चूस लिया, आत्मसात कर लिया और अपने में पचा डाला।", "rom": "Para jahāṁ hama yaha dekhate haiṁ ki yahūdī dharma īsāī dharma ko ātmasāta nahīṁ kara sakā, varan apanī sarvavijayinī duhitā—īsāī dharma—dvārā apane janma-sthāna se nirvāsita kara diyā gayā, aura kevala muṭṭhī bhara pārasī hī apane mahān dharma kī gāthā gāne ke lie aba avaśeṣa haiṁ,—vahāṁ bhārata meṁ eka ke bāda eka na jāne kitane sampradāyoṁ kā udaya huā aura unhoṁne vaidika dharma ko jaṛa se hilā sā diyā; kintu bhayaṁkara bhūkampa ke samaya samudra-taṭa ke jala ke samāna vaha kucha samaya paścāt hazār gunā balaśālī hokara sarvagrāsī āplāvana ke rūpa meṁ punaḥ lauṭane ke lie pīche haṭa gayā; aura jaba yaha sārā kolāhala śānta ho gayā, taba ina samasta dharma-sampradāyoṁ ko unakī dharma-mātā (hiṁdū dharma) kī virāṭ kāyā ne cūsa liyā, ātmasāta kara liyā aura apane meṁ pacā ḍālā.", "zh": "然而我們看到：猶太教未能同化基督教，反而被自己無往不勝的女兒——基督教——逐出自己的出生地；而祆教徒如今只剩下寥寥數人，來歌頌自己偉大的宗教。與此相對，在印度，一個又一個不知多少宗派相繼興起，幾乎把吠陀宗教連根搖動；但就像大地震時海邊的海水一樣，它過了一段時間後，以千倍的力量、如吞沒一切的洪水般，為了重新歸來而退後；當這一切喧鬧平息之後，印度教這位宗教之母的龐大身軀，便把所有這些宗教宗派都吸納、同化，並消化於自身之中。", "st": "complete", "doubt": false}, {"id": "HINDU-04", "g": "hindu", "pdf": 29, "book": 7, "hi": "वेदान्त दर्शन की अत्युच्च आध्यात्मिक उड़ानों से लेकर—आधुनिक विज्ञान के नवीनतम आविष्कार जिसकी केवल प्रतिध्वनि मात्र प्रतीत होते हैं, मूर्ति-पूजा के निम्न स्तरीय विचारों एवं तदनुषंगिक अनेकानेक पौराणिक दन्तकथाओं तक, और बौद्धों के अज्ञेयवाद तथा जैनों के निरीश्वरवाद—इनमें से प्रत्येक के लिए हिन्दू धर्म में स्थान है।", "rom": "Vedānta darśana kī atyucca ādhyātmika uṛānoṁ se lekara—ādhunika vijñāna ke navīnatama āviṣkāra jisakī kevala pratidhvani mātra pratīta hote haiṁ, mūrti-pūjā ke nimna starīya vicāroṁ evaṁ tadanuṣaṅgika anekāneka paurāṇika dantakathāoṁ taka, aura baud­dhoṁ ke ajñeyavāda tathā jainoṁ ke nirīśvaravāda—inameṁ se pratyeka ke lie hindū dharma meṁ sthāna hai.", "zh": "從吠檀多哲學極高的靈性飛翔——現代科學的最新發明看起來不過是它的回聲而已——一直到偶像崇拜的低層思想以及隨之而來的無數神話傳說，再到佛教的不可知論和耆那教的無神論——印度教中都為其中的每一種留有位置。", "st": "complete", "doubt": false}, {"id": "HINDU-05", "g": "hindu", "pdf": 29, "book": 7, "hi": "तब यह प्रश्न उठता है कि वह कौन सा एक सामान्य बिन्दु है, जहाँ पर इतनी विभिन्न दिशाओं में जानेवाली त्रिज्याएं केन्द्रस्थ होती हैं ?", "rom": "Taba yaha praśna uṭhatā hai ki vaha kauna sā eka sāmānya bindu hai, jahāṁ para itanī vibhinna diśāoṁ meṁ jānevālī trijyāẽ kendrastha hotī haiṁ?", "zh": "於是問題就出現了：那一個共同的中心點是什麼，朝著如此不同方向伸展的半徑都在那裡匯聚？", "st": "complete", "doubt": false}, {"id": "HINDU-06", "g": "hindu", "pdf": 29, "book": 7, "hi": "वह कौन सा एक सामान्य आधार है, जिस पर ये प्रचंड विरोधाभास आश्रित हैं ?", "rom": "Vaha kauna sā eka sāmānya ādhāra hai, jisa para ye pracaṇḍa virodhābhāsa āśrita haiṁ?", "zh": "那一個共同的基礎是什麼，這些強烈的矛盾都依附在它之上？", "st": "complete", "doubt": false}, {"id": "HINDU-07", "g": "hindu", "pdf": 29, "book": 7, "hi": "इसी प्रश्न का उत्तर देने का अब मैं प्रयत्न करूँगा।", "rom": "Isī praśna kā uttara dene kā aba maiṁ prayatna karūṁgā.", "zh": "現在，我就來嘗試回答這個問題。", "st": "complete", "doubt": false}, {"id": "HINDU-08", "g": "hindu", "pdf": 29, "book": 7, "hi": "हिन्दू जाति ने अपना धर्म श्रुति—वेदों से प्राप्त किया है।", "rom": "Hindū jāti ne apanā dharma śruti—vedoṁ se prāpta kiyā hai.", "zh": "印度民族是從天啟經典——吠陀——獲得自己的宗教的。", "st": "complete", "doubt": false}, {"id": "HINDU-09", "g": "hindu", "pdf": 29, "book": 7, "hi": "उनकी धारणा है कि वेद अनादि और अनन्त हैं।", "rom": "Unakī dhāraṇā hai ki veda anādi aura ananta haiṁ.", "zh": "他們認為，吠陀是無始無終的。", "st": "complete", "doubt": false}, {"id": "HINDU-10", "g": "hindu", "pdf": 29, "book": 7, "hi": "श्रोताओं को, सम्भव है, यह बात हास्यास्पद लगे कि कोई पुस्तक अनादि और अनन्त कैसे हो सकती है।", "rom": "Śrotāoṁ ko, sambhava hai, yaha bāta hāsyāspada lage ki koī pustaka anādi aura ananta kaise ho sakatī hai.", "zh": "聽眾們可能會覺得好笑：一本書怎麼可能是無始無終的呢？", "st": "complete", "doubt": false}, {"id": "HINDU-11", "g": "hindu", "pdf": 29, "book": 7, "hi": "किन्तु वेदों का अर्थ कोई पुस्तक है ही नहीं।", "rom": "Kintu vedoṁ kā artha koī pustaka hai hī nahīṁ.", "zh": "但吠陀的意思根本不是一本書。", "st": "complete", "doubt": false}, {"id": "HINDU-12", "g": "hindu", "pdf": 30, "book": 8, "hi": "वेदों का अर्थ है, भिन्न भिन्न कालों में भिन्न भिन्न व्यक्तियों द्वारा आविष्कृत आध्यात्मिक सत्यों का संचित कोष।", "rom": "Vedoṁ kā artha hai, bhinna bhinna kāloṁ meṁ bhinna bhinna vyaktiyoṁ dvārā āviṣkṛta ādhyātmika satyoṁ kā saṁcita koṣa.", "zh": "吠陀的意思是：在不同時代、由不同的人所發現的靈性真理的積累寶庫。", "st": "complete", "doubt": false}, {"id": "HINDU-13", "g": "hindu", "pdf": 30, "book": 8, "hi": "जिस प्रकार गुरुत्वाकर्षण का सिद्धान्त मनुष्यों के पता लगने के पूर्व से ही अपना काम करता चला आया था और आज यदि मनुष्य-जाति उसे भूल भी जाय, तो भी वह नियम अपना काम करता ही रहेगा, ठीक वही बात आध्यात्मिक जगत् का शासन करनेवाले नियमों के सम्बन्ध में भी है।", "rom": "Jisa prakāra gurutvākarṣaṇa kā siddhānta manuṣyoṁ ke patā lagane ke pūrva se hī apanā kāma karatā calā āyā thā aura āja yadi manuṣya-jāti use bhūla bhī jāya, to bhī vaha niyama apanā kāma karatā hī rahegā, ṭhīka vahī bāta ādhyātmika jagat kā śāsana karanevāle niyamoṁ ke sambandha meṁ bhī hai.", "zh": "正如萬有引力定律在人類發現它之前就一直在發揮作用，而且即使今天人類忘記了它，那條定律仍會繼續發揮作用；同樣的道理，也適用於支配靈性世界的定律。", "st": "complete", "doubt": false}, {"id": "HINDU-14", "g": "hindu", "pdf": 30, "book": 8, "hi": "एक आत्मा का दूसरी आत्मा के साथ और जीवात्मा का आत्माओं के परम पिता के साथ जो नैतिक तथा आध्यात्मिक सम्बन्ध हैं, वे उनके आविष्कार के पूर्व भी थे, और हम यदि उन्हें भूल भी जायें, तो भी बने रहेंगे।", "rom": "Eka ātmā kā dūsarī ātmā ke sātha aura jīvātmā kā ātmāoṁ ke parama pitā ke sātha jo naitika tathā ādhyātmika sambandha haiṁ, ve unake āviṣkāra ke pūrva bhī the, aura hama yadi unheṁ bhūla bhī jāyeṁ, to bhī bane raheṁge.", "zh": "一個靈魂與另一個靈魂之間、個體靈魂與眾靈魂的至高父親之間在道德上與靈性上的關係，在它們被發現之前就已經存在；即使我們忘記了它們，它們也仍然存在。", "st": "complete", "doubt": false}, {"id": "HINDU-15", "g": "hindu", "pdf": 30, "book": 8, "hi": "इन नियमों या सत्यों का आविष्कार करनेवाले ‘ऋषि’ कहलाते हैं और हम उनको पूर्णत्व तक पहुँची हुई आत्मा मानकर सम्मान देते हैं।", "rom": "Ina niyamoṁ yā satyoṁ kā āviṣkāra karanevāle ‘ṛṣi’ kahalāte haiṁ aura hama unako pūrṇatva taka pahũcī huī ātmā mānakara sammāna dete haiṁ.", "zh": "發現這些定律或真理的人被稱為『仙人』，我們尊敬他們，視他們為已達到圓滿的靈魂。", "st": "complete", "doubt": false}, {"id": "HINDU-16", "g": "hindu", "pdf": 30, "book": 8, "hi": "श्रोताओं को यह बतलाते हुए मुझे हर्ष होता है कि इन महानतम ऋषियों में कुछ स्त्रियाँ भी थीं।", "rom": "Śrotāoṁ ko yaha batalāte hue mujhe harṣa hotā hai ki ina mahānatama ṛṣiyoṁ meṁ kucha striyāṁ bhī thīṁ.", "zh": "我很高興告訴聽眾：在這些最偉大的仙人之中，也有一些是女性。", "st": "complete", "doubt": false}, {"id": "HINDU-17", "g": "hindu", "pdf": 30, "book": 8, "hi": "यहाँ यह कहा जा सकता है कि ये नियम, नियम के रूप में अनन्त भले ही हों, पर इनका आदि तो अवश्य ही होना चाहिए।", "rom": "Yahāṁ yaha kahā jā sakatā hai ki ye niyama, niyama ke rūpa meṁ ananta bhale hī hoṁ, para inakā ādi to avaśya hī honā cāhie.", "zh": "在這裡，有人可能會說：這些定律，即使作為定律是永恆的，也必定有一個開端。", "st": "complete", "doubt": false}, {"id": "HINDU-18", "g": "hindu", "pdf": 30, "book": 8, "hi": "वेद हमें यह सिखाते हैं कि सृष्टि का न आदि है, न अन्त।", "rom": "Veda hameṁ yaha sikhāte haiṁ ki sṛṣṭi kā na ādi hai, na anta.", "zh": "吠陀教導我們：創造既無開端，也無終結。", "st": "complete", "doubt": false}, {"id": "HINDU-19", "g": "hindu", "pdf": 30, "book": 8, "hi": "विज्ञान ने हमें सिद्ध कर दिखाया है कि समग्र विश्व की सारी ऊर्जा-समष्टि का परिमाण सदा एक सा रहता है।", "rom": "Vijñāna ne hameṁ siddha kara dikhāyā hai ki samagra viśva kī sārī ūrjā-samaṣṭi kā parimāṇa sadā eka sā rahatā hai.", "zh": "科學已經向我們證明：整個宇宙中全部能量的總量永遠保持不變。", "st": "complete", "doubt": false}, {"id": "HINDU-20", "g": "hindu", "pdf": 30, "book": 8, "hi": "तो फिर, यदि ऐसा कोई समय था, जब कि किसी वस्तु का अस्तित्व ही नहीं था, उस समय यह सम्पूर्ण व्यक्त ऊर्जा कहाँ थी ?", "rom": "To phira, yadi aisā koī samaya thā, jaba ki kisī vastu kā astitva hī nahīṁ thā, usa samaya yaha sampūrṇa vyakta ūrjā kahāṁ thī?", "zh": "那麼，如果曾經有那麼一個時刻，當時任何事物都不存在，那麼這全部已顯現的能量當時在哪裡呢？", "st": "complete", "doubt": false}, {"id": "HINDU-21", "g": "hindu", "pdf": 30, "book": 8, "hi": "कोई कोई कहते हैं कि ईश्वर में ही वह सब अव्यक्त रूप में निहित थी।", "rom": "Koī koī kahate haiṁ ki īśvara meṁ hī vaha saba avyakta rūpa meṁ nihita thī.", "zh": "有人說：這一切當時都以未顯現的形式蘊含在上帝之中。", "st": "complete", "doubt": false}, {"id": "HINDU-22", "g": "hindu", "pdf": 30, "book": 8, "hi": "तब तो ईश्वर कभी अव्यक्त और कभी व्यक्त है; इससे तो वह विकारशील हो जायगा।", "rom": "Taba to īśvara kabhī avyakta aura kabhī vyakta hai; isase to vaha vikāraśīla ho jāyagā.", "zh": "那麼，上帝就時而未顯現、時而顯現；這樣一來，祂就成了會變化的了。", "st": "complete", "doubt": false}, {"id": "HINDU-23", "g": "hindu", "pdf": 30, "book": 8, "hi": "प्रत्येक विकारशील पदार्थ यौगिक होता है और हर यौगिक पदार्थ में वह परिवर्तन अवश्यम्भावी है, जिसे हम विनाश कहते हैं।", "rom": "Pratyeka vikāraśīla padārtha yaugika hotā hai aura hara yaugika padārtha meṁ vaha parivartana avaśyambhāvī hai, jise hama vināśa kahate haiṁ.", "zh": "每一個會變化的事物都是複合的，而每一個複合事物中那種變化都是必然的，我們稱之為毀滅。", "st": "complete", "doubt": false}, {"id": "HINDU-24", "g": "hindu", "pdf": 30, "book": 8, "hi": "इस तरह तो ईश्वर की मृत्यु हो जायगी, जो अनर्गल है।", "rom": "Isa taraha to īśvara kī mṛtyu ho jāyagī, jo anargala hai.", "zh": "這樣一來，上帝就會死亡，這是荒謬的。", "st": "complete", "doubt": false}, {"id": "HINDU-25", "g": "hindu", "pdf": 30, "book": 8, "hi": "अतः ऐसा समय कभी नहीं था, जब यह सृष्टि नहीं थी।", "rom": "Ataḥ aisā samaya kabhī nahīṁ thā, jaba yaha sṛṣṭi nahīṁ thī.", "zh": "因此，從來沒有過這樣一個時刻：當時這個創造並不存在。", "st": "complete", "doubt": false}, {"id": "HINDU-26", "g": "hindu", "pdf": 30, "book": 8, "hi": "मैं एक उपमा दूँ: स्रष्टा और सृष्टि मानो दो रेखाएँ हैं, जिनका न आदि है, न अन्त, और जो समानान्तर चलती हैं।", "rom": "Maiṁ eka upamā dūṁ: sraṣṭā aura sṛṣṭi māno do rekhāẽ haiṁ, jinakā na ādi hai, na anta, aura jo samānāntara calatī haiṁ.", "zh": "我打一個比喻：創造者與被創造的世界就好像兩條線，既無開端、也無終結，並且平行前行。", "st": "complete", "doubt": false}, {"id": "HINDU-27", "g": "hindu", "pdf": 30, "book": 8, "hi": "ईश्वर नित्य क्रियाशील विधाता है, जिसकी शक्ति से प्रलय-पयोधि में से नित्यशः एक के बाद एक ब्रह्माण्ड का सृजन होता है, वे कुछ काल तक गतिमान रहते हैं और तत्पश्चात् वे पुनः विनष्ट कर दिये जाते हैं।", "rom": "Īśvara nitya kriyāśīla vidhātā hai, jisakī śakti se pralaya-payodhi meṁ se nityaśaḥ eka ke bāda eka brahmāṇḍa kā sṛjana hotā hai, ve kucha kāla taka gatimāna rahate haiṁ aura tatpaścāt ve punaḥ vinaṣṭa kara diye jāte haiṁ.", "zh": "上帝是永恆活動的造物主，憑藉祂的力量，從滅世之洋中不斷地一個接一個地創造出宇宙；這些宇宙運行一段時間之後，又再度被毀滅。", "st": "complete", "doubt": false}, {"id": "HINDU-28", "g": "hindu", "pdf": 30, "book": 8, "hi": "सूर्याचन्द्रमसौ धाता यथापूर्वमकल्पयत् अर्थात् इस सूर्य और इस चन्द्रमा को विधाता ने पूर्व कल्पों के सूर्य और चन्द्रमा के समान निर्मित किया है—इस वाक्य का नित्य पाठ प्रत्येक हिन्दू बालक प्रतिदिन करता है।", "rom": "Sūryācandramasau dhātā yathāpūrvam akalpayat arthāt isa sūrya aura isa candramā ko vidhātā ne pūrva kalpoṁ ke sūrya aura candramā ke samāna nirmita kiyā hai—isa vākya kā nitya pāṭha pratyeka hindū bālaka pratidina karatā hai.", "zh": "「造物主一如往昔，創造了日與月」——也就是說，造物主把這個太陽和這個月亮，造得與過去各劫的太陽和月亮相同——這句話，每一個印度教孩子每天都會誦念。", "st": "complete", "doubt": false}, {"id": "HINDU-29", "g": "hindu", "pdf": 30, "book": 8, "hi": "यहाँ पर मैं खड़ा हूँ और अपनी आँखें बन्द करके यदि मैं अपने अस्तित्व—‘मैं’, ‘मैं’, ‘मैं’ को समझने का प्रयत्न करूँ, तो मुझमें किस भाव का उदय होता है ?", "rom": "Yahāṁ para maiṁ khaṛā hūṁ aura apanī āṁkheṁ banda karake yadi maiṁ apane astitva—‘maiṁ’, ‘maiṁ’, ‘maiṁ’ ko samajhane kā prayatna karūṁ, to mujhameṁ kisa bhāva kā udaya hotā hai?", "zh": "就在這裡，我站著，閉上眼睛，如果我試著去理解我自己的存在——『我』、『我』、『我』——那麼，在我心中會升起什麼樣的感覺呢？", "st": "complete", "doubt": false}, {"id": "HINDU-30", "g": "hindu", "pdf": 30, "book": 8, "hi": "इस भाव का कि मैं शरीर हूँ।", "rom": "Isa bhāva kā ki maiṁ śarīra hūṁ.", "zh": "那就是：我是身體的感覺。", "st": "complete", "doubt": false}, {"id": "HINDU-31", "g": "hindu", "pdf": 30, "book": 8, "hi": "तो क्या मैं भौतिक पदार्थों के संघात के", "rom": "To kyā maiṁ bhautika padārthoṁ ke saṁghāta ke", "zh": "那麼，難道我只是物質元素的集合的——", "st": "truncated", "doubt": false}];
